pub(crate) async fn handle_get_sorafs_providers(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let Some(cache) = state.sorafs_cache.clone() else {
        return feature_disabled("sorafs discovery API is not enabled on this node");
    };
    let query = match ProviderListQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);

    let mut cache_guard = cache.write().await;
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or(0);
    let pruned = cache_guard.prune_stale(now);
    if pruned > 0 {
        warn!(removed = pruned, "pruned stale SoraFS provider adverts");
    }
    record_range_capability_metrics(&cache_guard, &state.telemetry);
    let total_count = cache_guard.len();
    let truncated = total_count > limit;
    let mut providers = Vec::with_capacity(total_count.min(limit));
    for record in cache_guard.records().take(limit) {
        match advert_to_json(
            record.fingerprint(),
            record.advert(),
            record.known_capabilities(),
            record.warnings(),
        ) {
            Ok(value) => providers.push(value),
            Err(err) => {
                error!(%err, "failed to serialize provider advert to JSON");
            }
        }
    }

    let response = json_object(vec![
        json_entry("count", total_count as u64),
        json_entry("returned_count", providers.len() as u64),
        json_entry("limit", limit as u64),
        json_entry("truncated", truncated),
        json_entry("providers", Value::Array(providers)),
    ]);
    JsonBody(response).into_response()
}

pub(crate) async fn handle_get_sorafs_storage_peers(
    State(state): State<SharedAppState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Response {
    let query = match StoragePeersReadbackQuery::parse(raw_query.as_deref()) {
        Ok(query) => query,
        Err(err) => return err.into_response(),
    };
    let limit = normalize_limit(query.limit);
    let publish = &state.sorafs_publish_discovery;
    let count = publish.pin_torii_urls.len();
    let pin_torii_urls = publish
        .pin_torii_urls
        .iter()
        .take(limit)
        .cloned()
        .map(Value::from)
        .collect::<Vec<_>>();
    let returned_count = pin_torii_urls.len();
    let mut response = Map::new();
    response.insert("source".into(), Value::from("config"));
    response.insert(
        "gateway_base_url".into(),
        publish
            .gateway_base_url
            .as_ref()
            .map_or(Value::Null, |url| Value::from(url.clone())),
    );
    response.insert("pin_torii_urls".into(), Value::Array(pin_torii_urls));
    response.insert("count".into(), Value::from(count as u64));
    response.insert("returned_count".into(), Value::from(returned_count as u64));
    response.insert("limit".into(), Value::from(limit as u64));
    response.insert("truncated".into(), Value::from(count > limit));
    JsonBody(Value::Object(response)).into_response()
}

pub(crate) async fn handle_get_sorafs_governance_dag_dashboard(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
) -> Response {
    let (index, source_path, encoded_len, blake3_hex, etag) =
        match load_governance_dag_mirror_index(&state) {
            Ok(value) => value,
            Err(response) => return response,
        };
    if let Some(response) = governance_dag_not_modified_response(&headers, &etag) {
        return response;
    }

    let blocks = index
        .get("blocks")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut payload_counts = Map::new();
    let mut first_sequence: Option<u64> = None;
    let mut last_sequence: Option<u64> = None;
    let mut last_timestamp: Option<u64> = None;
    for block in &blocks {
        if let Some(kind) = block.get("payload_kind").and_then(Value::as_str) {
            let next = payload_counts
                .get(kind)
                .and_then(Value::as_u64)
                .unwrap_or(0)
                .saturating_add(1);
            payload_counts.insert(kind.to_string(), Value::from(next));
        }
        if let Some(sequence) = block.get("sequence").and_then(Value::as_u64) {
            first_sequence = Some(first_sequence.map_or(sequence, |current| current.min(sequence)));
            last_sequence = Some(last_sequence.map_or(sequence, |current| current.max(sequence)));
        }
        if let Some(timestamp) = block.get("timestamp").and_then(Value::as_u64) {
            last_timestamp =
                Some(last_timestamp.map_or(timestamp, |current| current.max(timestamp)));
        }
    }

    let mut response = Map::new();
    response.insert(
        "schema".into(),
        Value::from("sorafs.governance_dag.dashboard.v1"),
    );
    response.insert("source".into(), Value::from("local_mirror_index"));
    response.insert("source_path".into(), Value::from(source_path));
    response.insert("encoded_len".into(), Value::from(encoded_len));
    response.insert("blake3".into(), Value::from(blake3_hex));
    response.insert(
        "mirror_generated_at".into(),
        index.get("generated_at").cloned().unwrap_or(Value::Null),
    );
    response.insert(
        "head".into(),
        index.get("head").cloned().unwrap_or(Value::Null),
    );
    response.insert(
        "block_count".into(),
        index
            .get("block_count")
            .cloned()
            .unwrap_or_else(|| Value::from(blocks.len() as u64)),
    );
    response.insert(
        "indexed_block_count".into(),
        Value::from(blocks.len() as u64),
    );
    response.insert(
        "first_sequence".into(),
        first_sequence.map_or(Value::Null, Value::from),
    );
    response.insert(
        "last_sequence".into(),
        last_sequence.map_or(Value::Null, Value::from),
    );
    response.insert(
        "last_timestamp".into(),
        last_timestamp.map_or(Value::Null, Value::from),
    );
    response.insert("payload_kind_counts".into(), Value::Object(payload_counts));
    governance_dag_json_response(Value::Object(response), &etag)
}

