pub(crate) async fn handle_post_sorafs_appeal_finance_deposit_settle(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs appeal finance deposit settlement API is not enabled on this node",
        );
    }
    let verified =
        match require_appeal_finance_request_auth(&state, &headers, &method, &uri, body.as_ref()) {
            Ok(verified) => verified,
            Err(response) => return response,
        };
    let req = match json::from_slice::<AppealFinanceDepositSettleRequestDto>(body.as_ref()) {
        Ok(req) => req,
        Err(err) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!("failed to decode SoraFS appeal finance deposit settlement JSON: {err}"),
            );
        }
    };
    let (expected, record) = match confirm_appeal_finance_deposit_record(
        &state,
        &req.deposit_confirmation,
        &verified.account,
    ) {
        Ok(confirmation) => confirmation,
        Err(response) => return response,
    };
    let policy = &state.sorafs_appeal_finance_policy;
    let config = policy.settlement();
    let deposit_xor =
        match parse_appeal_quantity_literal("deposit_xor", &expected.deposit_xor.to_string()) {
            Ok(value) => value,
            Err(err) => return json_error(StatusCode::BAD_REQUEST, err.to_string()),
        };
    let verdict = match appeal_verdict_from_request(&req.outcome) {
        Ok(value) => value,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err),
    };
    let panel_size = req
        .panel_size
        .unwrap_or_else(|| config.default_panel_size());
    let breakdown = match config.settle(deposit_xor, panel_size, verdict) {
        Ok(value) => value,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err.to_string()),
    };
    let execution =
        match appeal_finance_deposit_settlement_execution(&expected, &record, &breakdown) {
            Ok(execution) => execution,
            Err(err) => return json_error(StatusCode::BAD_REQUEST, err),
        };
    (
        StatusCode::OK,
        JsonBody(appeal_finance_deposit_settlement_execution_json(
            policy, &expected, &record, verdict, panel_size, &breakdown, &execution,
        )),
    )
        .into_response()
}

pub(crate) async fn handle_post_sorafs_appeal_finance_deposit_submit_settlement(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs appeal finance deposit settlement submitter API is not enabled on this node",
        );
    }
    let verified =
        match require_appeal_finance_request_auth(&state, &headers, &method, &uri, body.as_ref()) {
            Ok(verified) => verified,
            Err(response) => return response,
        };
    let req = match json::from_slice::<AppealFinanceDepositSettleRequestDto>(body.as_ref()) {
        Ok(req) => req,
        Err(err) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!(
                    "failed to decode SoraFS appeal finance deposit settlement submission JSON: {err}"
                ),
            );
        }
    };
    let (expected, record, finalized_cursor) =
        match load_appeal_finance_deposit_record_for_reconciliation(
            &state,
            &req.deposit_confirmation,
            &verified.account,
        ) {
            Ok(value) => value,
            Err(response) => return response,
        };
    match submit_appeal_finance_deposit_settlement_step(
        &state,
        expected,
        record,
        finalized_cursor,
        &req.outcome,
        req.panel_size,
    )
    .await
    {
        Ok((status, body)) => (status, JsonBody(body)).into_response(),
        Err(response) => response,
    }
}

async fn submit_appeal_finance_deposit_settlement_step(
    state: &SharedAppState,
    expected: AppealFinanceDepositExpectation,
    record: AssetEscrowRecord,
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
    outcome: &str,
    panel_size: Option<u32>,
) -> Result<(StatusCode, Value), Response> {
    let policy = &state.sorafs_appeal_finance_policy;
    let config = policy.settlement();
    let deposit_xor =
        match parse_appeal_quantity_literal("deposit_xor", &expected.deposit_xor.to_string()) {
            Ok(value) => value,
            Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err.to_string())),
        };
    let verdict = match appeal_verdict_from_request(outcome) {
        Ok(value) => value,
        Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err)),
    };
    let panel_size = panel_size.unwrap_or_else(|| config.default_panel_size());
    let breakdown = match config.settle(deposit_xor, panel_size, verdict) {
        Ok(value) => value,
        Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err.to_string())),
    };
    let reconciliation = match appeal_finance_deposit_settlement_reconciliation(
        &expected, &record, policy, verdict, panel_size, &breakdown,
    ) {
        Ok(value) => value,
        Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err)),
    };
    let execution =
        match appeal_finance_deposit_settlement_execution(&expected, &record, &breakdown) {
            Ok(value) => value,
            Err(err) => return Err(json_error(StatusCode::BAD_REQUEST, err)),
        };

    if reconciliation.status == "settled" {
        return Ok((
            StatusCode::OK,
            appeal_finance_deposit_settlement_submission_json(
                policy,
                &expected,
                &record,
                verdict,
                panel_size,
                &breakdown,
                &reconciliation,
                None,
                None,
                0,
                "already_reconciled",
                None,
                "not_applicable",
                None,
            ),
        ));
    }
    if reconciliation.status == "mismatch" {
        return Ok((
            StatusCode::CONFLICT,
            appeal_finance_deposit_settlement_submission_json(
                policy,
                &expected,
                &record,
                verdict,
                panel_size,
                &breakdown,
                &reconciliation,
                None,
                None,
                0,
                "mismatch",
                None,
                "not_applicable",
                None,
            ),
        ));
    }

    let Some(step) =
        appeal_finance_deposit_next_settlement_submission_step(&reconciliation, &execution)
    else {
        return Err(json_error(
            StatusCode::CONFLICT,
            "SoraFS appeal finance settlement state has no submitter action",
        ));
    };
    let Some(submitter) = state.sorafs_appeal_settlement_submitter.as_ref() else {
        return Ok((
            StatusCode::SERVICE_UNAVAILABLE,
            appeal_finance_deposit_settlement_submission_json(
                policy,
                &expected,
                &record,
                verdict,
                panel_size,
                &breakdown,
                &reconciliation,
                Some(step),
                None,
                0,
                "submitter_not_configured",
                None,
                "not_applicable",
                None,
            ),
        ));
    };
    if execution.steps.iter().any(|planned_step| {
        submitter
            .signer_for(&planned_step.required_authority, finalized_cursor.height)
            .is_err()
    }) {
        return Ok((
            StatusCode::SERVICE_UNAVAILABLE,
            appeal_finance_deposit_settlement_submission_json(
                policy,
                &expected,
                &record,
                verdict,
                panel_size,
                &breakdown,
                &reconciliation,
                Some(step),
                None,
                submitter.signer_count(finalized_cursor.height),
                "missing_required_signer",
                None,
                "not_applicable",
                None,
            ),
        ));
    }

    use sorafs_node::appeal_finance_transaction_forwarder::{
        AppealFinanceOperationV1, AppealFinanceTransactionContextV1,
        AppealFinanceTransactionEnqueueResultV1,
    };
    let operation = match step.action {
        "drawdown_non_refund" => AppealFinanceOperationV1::Drawdown(DrawdownAssetLock::new(
            expected.escrow_id,
            step.amount_xor.clone(),
            record.remaining_amount.clone(),
        )),
        "cancel_refund" => AppealFinanceOperationV1::Cancel(CancelAssetLock::new(
            expected.escrow_id,
            record.remaining_amount.clone(),
        )),
        other => {
            return Err(json_error(
                StatusCode::BAD_REQUEST,
                format!("unsupported SoraFS appeal finance settlement step `{other}`"),
            ));
        }
    };
    let reconciliation_context = norito::to_bytes(&AppealFinanceSettlementOutboxContextV1 {
        version: APPEAL_FINANCE_SETTLEMENT_OUTBOX_CONTEXT_VERSION_V1,
        policy_digest: policy.policy_digest,
        settlement: AppealFinanceSettlementSnapshotV1::from_policy_and_breakdown(
            policy, &breakdown,
        ),
        expected: expected.clone(),
        outcome: verdict.to_string(),
        panel_size,
    })
    .map_err(|error| {
        json_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!("failed to encode SoraFS appeal finance settlement outbox context: {error}"),
        )
    })?;
    let context = AppealFinanceTransactionContextV1 {
        chain_id: (*state.chain_id).clone(),
        finalized_cursor,
        expected_record: Some(record.clone()),
        reconciliation_context,
    };
    let enqueue = match submitter.forwarder.enqueue_unsigned_operation(
        step.required_authority.clone(),
        operation,
        &context,
    ) {
        Ok(enqueue) => enqueue,
        Err(
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarderError::IdentityConflict
            | sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarderError::DeadLetterConflict,
        ) => {
            return Ok((
                StatusCode::CONFLICT,
                appeal_finance_deposit_settlement_submission_json(
                    policy,
                    &expected,
                    &record,
                    verdict,
                    panel_size,
                    &breakdown,
                    &reconciliation,
                    Some(step),
                    None,
                    submitter.signer_count(finalized_cursor.height),
                    "durable_identity_conflict",
                    None,
                    "not_applicable",
                    None,
                ),
            ));
        }
        Err(error) => {
            return Err(json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                format!("failed to durably enqueue SoraFS appeal finance settlement: {error}"),
            ));
        }
    };
    let operation_id_hex = hex::encode(enqueue.operation_id());
    let status = match enqueue {
        AppealFinanceTransactionEnqueueResultV1::Inserted { .. } => "durably_enqueued",
        AppealFinanceTransactionEnqueueResultV1::Existing { .. } => "already_durably_enqueued",
    };

    Ok((
        StatusCode::ACCEPTED,
        appeal_finance_deposit_settlement_submission_json(
            policy,
            &expected,
            &record,
            verdict,
            panel_size,
            &breakdown,
            &reconciliation,
            Some(step),
            Some(&operation_id_hex),
            submitter.signer_count(finalized_cursor.height),
            status,
            None,
            "awaiting_finalized_commit",
            None,
        ),
    ))
}

const SORAFS_APPEAL_FINANCE_FORWARDER_SCAN_LIMIT_V1: usize = 256;

fn appeal_finance_finalized_cursor_from_view(
    view: &impl StateReadOnly,
) -> Option<sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1> {
    u64::try_from(view.block_hashes().len())
        .ok()
        .zip(view.block_hashes().last())
        .map(|(height, hash)| {
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1 {
                height,
                block_hash: *hash.as_ref(),
            }
        })
        .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsAppealFinanceForwarderScanV1 {
    scanned: usize,
    finalized: usize,
    signed: usize,
    submitted: usize,
    deferred: usize,
    dead_lettered: usize,
    followups_enqueued: usize,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsAppealFinanceForwarderCursorV1 {
    after_sequence: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppealFinanceSubmissionDispositionV1 {
    Submitted,
    DefinitelyNotSubmitted,
    Rejected,
    Ambiguous,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppealFinanceDeliverySubmitOutcomeV1 {
    Submitted,
    Deferred,
    DeadLettered,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppealFinanceCommittedExternalOutcomeV1 {
    Applied,
    Rejected,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppealFinanceAuthoritativeTransactionOutcomeV1 {
    Absent,
    Applied {
        block_height: u64,
        block_hash: [u8; 32],
        block_timestamp_ms: u64,
    },
    Rejected,
    Unavailable,
}

fn classify_local_appeal_finance_submission(
    error: &iroha_core::queue::Error,
) -> AppealFinanceSubmissionDispositionV1 {
    match error {
        iroha_core::queue::Error::InBlockchain | iroha_core::queue::Error::IsInQueue => {
            AppealFinanceSubmissionDispositionV1::Submitted
        }
        iroha_core::queue::Error::PlanJournalDurabilityIndeterminate { .. } => {
            AppealFinanceSubmissionDispositionV1::Ambiguous
        }
        iroha_core::queue::Error::Expired => AppealFinanceSubmissionDispositionV1::Rejected,
        _ => AppealFinanceSubmissionDispositionV1::DefinitelyNotSubmitted,
    }
}

fn classify_exact_appeal_finance_entrypoint_outcome(
    expected_hash: &HashOf<SignedTransaction>,
    block_available: bool,
    applied_block: Option<(u64, [u8; 32], u64)>,
    results: impl IntoIterator<
        Item = (
            HashOf<SignedTransaction>,
            AppealFinanceCommittedExternalOutcomeV1,
        ),
    >,
) -> AppealFinanceAuthoritativeTransactionOutcomeV1 {
    if !block_available {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    let mut exact = results
        .into_iter()
        .filter_map(|(hash, outcome)| (&hash == expected_hash).then_some(outcome));
    let Some(outcome) = exact.next() else {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    };
    if exact.next().is_some() {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    match outcome {
        AppealFinanceCommittedExternalOutcomeV1::Applied => applied_block.map_or(
            AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable,
            |(block_height, block_hash, block_timestamp_ms)| {
                AppealFinanceAuthoritativeTransactionOutcomeV1::Applied {
                    block_height,
                    block_hash,
                    block_timestamp_ms,
                }
            },
        ),
        AppealFinanceCommittedExternalOutcomeV1::Rejected => {
            AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected
        }
    }
}

fn inspect_indexed_appeal_finance_transaction(
    kura: &iroha_core::kura::Kura,
    transaction_hash: &HashOf<SignedTransaction>,
    block_height: NonZeroUsize,
    expected_block_hash: HashOf<BlockHeader>,
) -> AppealFinanceAuthoritativeTransactionOutcomeV1 {
    let Some(block) = kura.get_block(block_height) else {
        return classify_exact_appeal_finance_entrypoint_outcome(
            transaction_hash,
            false,
            None,
            std::iter::empty::<(
                HashOf<SignedTransaction>,
                AppealFinanceCommittedExternalOutcomeV1,
            )>(),
        );
    };
    let Ok(block_height_u64) = u64::try_from(block_height.get()) else {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    };
    if block.header().height().get() != block_height_u64 || block.hash() != expected_block_hash {
        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    let block_timestamp_ms =
        u64::try_from(block.header().creation_time().as_millis()).unwrap_or(u64::MAX);
    let block_hash = *expected_block_hash.as_ref();
    let external_entrypoint_count = block.external_entrypoint_count();
    classify_exact_appeal_finance_entrypoint_outcome(
        transaction_hash,
        true,
        Some((block_height_u64, block_hash, block_timestamp_ms)),
        block
            .entrypoint_results()
            .take(external_entrypoint_count)
            .filter_map(|(_, entrypoint, result)| {
                let TransactionEntrypoint::External(transaction) = entrypoint else {
                    return None;
                };
                let outcome = if result.0.is_ok() {
                    AppealFinanceCommittedExternalOutcomeV1::Applied
                } else {
                    AppealFinanceCommittedExternalOutcomeV1::Rejected
                };
                Some((transaction.hash(), outcome))
            }),
    )
}

fn observe_appeal_finance_finalized_state(
    state: &SharedAppState,
    escrow_id: &EscrowId,
    transaction_hash: Option<&HashOf<SignedTransaction>>,
) -> Option<(
    sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
    Option<AssetEscrowRecord>,
    Option<AppealFinanceAuthoritativeTransactionOutcomeV1>,
)> {
    let view = state.state.view();
    let finalized_cursor = appeal_finance_finalized_cursor_from_view(&view)?;
    let record = view.world().asset_escrows().get(escrow_id).cloned();
    let transaction_outcome =
        transaction_hash.map(
            |transaction_hash| match view.transactions().get(transaction_hash) {
                None => AppealFinanceAuthoritativeTransactionOutcomeV1::Absent,
                Some(block_height) if block_height.get() > view.block_hashes().len() => {
                    AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable
                }
                Some(block_height) => {
                    let Some(expected_block_hash) = view
                        .block_hashes()
                        .get(block_height.get().saturating_sub(1))
                        .copied()
                    else {
                        return AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable;
                    };
                    inspect_indexed_appeal_finance_transaction(
                        view.kura(),
                        transaction_hash,
                        block_height,
                        expected_block_hash,
                    )
                }
            },
        );
    Some((finalized_cursor, record, transaction_outcome))
}

#[cfg(test)]
mod appeal_finance_authoritative_outcome_tests {
    use super::*;

    fn transaction_hash(byte: u8) -> HashOf<SignedTransaction> {
        HashOf::from_untyped_unchecked(Hash::prehashed([byte; 32]))
    }

    #[test]
    fn exact_finalized_transaction_outcome_rejects_missing_and_duplicate_index_entries() {
        let expected = transaction_hash(1);
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &expected,
                false,
                None,
                Vec::<(
                    HashOf<SignedTransaction>,
                    AppealFinanceCommittedExternalOutcomeV1,
                )>::new(),
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable
        );
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &expected,
                true,
                Some((1, [2; 32], 3)),
                [(
                    transaction_hash(2),
                    AppealFinanceCommittedExternalOutcomeV1::Applied,
                )],
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable
        );
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &expected,
                true,
                Some((1, [2; 32], 3)),
                [
                    (
                        expected.clone(),
                        AppealFinanceCommittedExternalOutcomeV1::Applied,
                    ),
                    (expected, AppealFinanceCommittedExternalOutcomeV1::Applied,),
                ],
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable
        );
    }

    #[test]
    fn exact_finalized_transaction_outcome_distinguishes_apply_and_reject() {
        let applied = transaction_hash(3);
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &applied,
                true,
                Some((7, [9; 32], 11)),
                [(
                    applied.clone(),
                    AppealFinanceCommittedExternalOutcomeV1::Applied,
                )],
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Applied {
                block_height: 7,
                block_hash: [9; 32],
                block_timestamp_ms: 11,
            }
        );
        let rejected = transaction_hash(4);
        assert_eq!(
            classify_exact_appeal_finance_entrypoint_outcome(
                &rejected,
                true,
                Some((8, [10; 32], 12)),
                [(
                    rejected.clone(),
                    AppealFinanceCommittedExternalOutcomeV1::Rejected,
                )],
            ),
            AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected
        );
    }
}

pub(crate) fn spawn_sorafs_appeal_finance_forwarder_worker(
    state: SharedAppState,
    shutdown_signal: ShutdownSignal,
) {
    let Some(submitter) = state.sorafs_appeal_settlement_submitter.as_ref() else {
        debug!("SoraFS appeal-finance forwarder disabled: storage is disabled");
        return;
    };
    let worker_interval = submitter.worker_scan_interval();
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(worker_interval);
        let mut cursor = SorafsAppealFinanceForwarderCursorV1::default();
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
        loop {
            tokio::select! {
                () = shutdown_signal.receive() => break,
                _ = interval.tick() => {
                    let scan = run_sorafs_appeal_finance_forwarder_scan(&state, &mut cursor).await;
                    if scan.scanned != 0 {
                        debug!(
                            scanned = scan.scanned,
                            finalized = scan.finalized,
                            signed = scan.signed,
                            submitted = scan.submitted,
                            deferred = scan.deferred,
                            dead_lettered = scan.dead_lettered,
                            followups_enqueued = scan.followups_enqueued,
                            "processed durable SoraFS appeal-finance deliveries"
                        );
                    }
                }
            }
        }
    });
}

pub(crate) async fn run_sorafs_appeal_finance_forwarder_scan(
    state: &SharedAppState,
    cursor: &mut SorafsAppealFinanceForwarderCursorV1,
) -> SorafsAppealFinanceForwarderScanV1 {
    use sorafs_node::appeal_finance_transaction_forwarder::{
        AppealFinanceOperationReconciliationV1, AppealFinanceTransactionDeliveryStateV1,
        AppealFinanceTransactionForwarderError, reconcile_appeal_finance_operation_v1,
    };

    let mut scan = SorafsAppealFinanceForwarderScanV1::default();
    let Some(submitter) = state.sorafs_appeal_settlement_submitter.as_ref() else {
        return scan;
    };
    let pending = match submitter.forwarder.pending_after(
        cursor.after_sequence,
        SORAFS_APPEAL_FINANCE_FORWARDER_SCAN_LIMIT_V1,
    ) {
        Ok(pending) => pending,
        Err(error) => {
            warn!(%error, "failed to load durable SoraFS appeal-finance deliveries");
            return scan;
        }
    };
    for delivery in pending {
        cursor.after_sequence = Some(delivery.sequence);
        scan.scanned = scan.scanned.saturating_add(1);
        let request = match submitter
            .forwarder
            .operation_for_reconciliation(delivery.operation_id)
        {
            Ok(request) => request,
            Err(_) => {
                scan.deferred = scan.deferred.saturating_add(1);
                continue;
            }
        };
        let signed_transaction = delivery
            .signed_transaction_bytes
            .as_deref()
            .and_then(decode_appeal_finance_signed_transaction);
        let transaction_hash = signed_transaction.as_ref().map(SignedTransaction::hash);
        let Some((finalized_cursor, record, transaction_outcome)) =
            observe_appeal_finance_finalized_state(
                state,
                request.operation.escrow_id(),
                transaction_hash.as_ref(),
            )
        else {
            scan.deferred = scan.deferred.saturating_add(1);
            continue;
        };
        let policy_status =
            appeal_finance_outbox_policy_status(&request, &state.sorafs_appeal_finance_policy);
        if policy_status == AppealFinanceOutboxPolicyStatusV1::InvalidContext {
            if submitter
                .forwarder
                .mark_invalid_context(delivery.operation_id, finalized_cursor)
                .is_ok()
            {
                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
            } else {
                scan.deferred = scan.deferred.saturating_add(1);
            }
            continue;
        }
        let reconciliation = match reconcile_appeal_finance_operation_v1(
            &request,
            finalized_cursor,
            record.as_ref(),
        ) {
            Ok(reconciliation) => reconciliation,
            Err(AppealFinanceTransactionForwarderError::StaleFinalizedCursor) => {
                if submitter
                    .forwarder
                    .mark_stale_finalized_cursor(delivery.operation_id, finalized_cursor)
                    .is_ok()
                {
                    scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                } else {
                    scan.deferred = scan.deferred.saturating_add(1);
                }
                continue;
            }
            Err(_) => {
                scan.deferred = scan.deferred.saturating_add(1);
                continue;
            }
        };
        let exact_transaction_applied = signed_transaction.as_ref().and_then(|_| {
            if let Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Applied {
                block_height,
                block_hash,
                block_timestamp_ms,
            }) = transaction_outcome
            {
                Some((block_height, block_hash, block_timestamp_ms))
            } else {
                None
            }
        });
        if let Some((applied_block_height, applied_block_hash, applied_block_timestamp_ms)) =
            exact_transaction_applied
        {
            let receipt_ready = match &request.operation {
                sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Open(
                    _,
                ) => true,
                _ => {
                    let Some(post_record) = appeal_finance_exact_applied_post_record(
                        &request,
                        applied_block_timestamp_ms,
                    ) else {
                        if submitter
                            .forwarder
                            .mark_invalid_context(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                        continue;
                    };
                    publish_finalized_appeal_finance_receipt(
                        state,
                        submitter,
                        &request,
                        &delivery,
                        applied_block_height,
                        applied_block_hash,
                        &post_record,
                    )
                }
            };
            if !receipt_ready {
                scan.deferred = scan.deferred.saturating_add(1);
                continue;
            }
            let followup_enqueued = if matches!(
                &request.operation,
                sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Drawdown(
                    _
                )
            ) {
                let Some(record) = record.as_ref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let Some(enqueued) =
                    enqueue_appeal_finance_followup(submitter, &request, finalized_cursor, record)
                else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                enqueued
            } else {
                false
            };
            match submitter
                .forwarder
                .mark_semantic_finalized(delivery.operation_id, finalized_cursor)
            {
                Ok(()) => {
                    scan.finalized = scan.finalized.saturating_add(1);
                    if followup_enqueued {
                        scan.followups_enqueued = scan.followups_enqueued.saturating_add(1);
                    }
                }
                Err(_) => scan.deferred = scan.deferred.saturating_add(1),
            }
            continue;
        }
        match reconciliation {
            AppealFinanceOperationReconciliationV1::Finalized => {
                let Some(record) = record.as_ref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let Some(followup_enqueued) =
                    enqueue_appeal_finance_followup(submitter, &request, finalized_cursor, record)
                else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match submitter
                    .forwarder
                    .mark_semantic_finalized(delivery.operation_id, finalized_cursor)
                {
                    Ok(()) => {
                        scan.finalized = scan.finalized.saturating_add(1);
                        if followup_enqueued {
                            scan.followups_enqueued = scan.followups_enqueued.saturating_add(1);
                        }
                    }
                    Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                }
                continue;
            }
            AppealFinanceOperationReconciliationV1::Conflict => {
                match transaction_outcome {
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected) => {
                        match mark_appeal_finance_transaction_rejected(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Some(
                        AppealFinanceAuthoritativeTransactionOutcomeV1::Absent
                        | AppealFinanceAuthoritativeTransactionOutcomeV1::Applied { .. },
                    )
                    | None => {
                        if submitter
                            .forwarder
                            .mark_finalized_conflict(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                    }
                }
                continue;
            }
            AppealFinanceOperationReconciliationV1::Ready => {}
        }
        if matches!(
            transaction_outcome,
            Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected)
        ) {
            match mark_appeal_finance_transaction_rejected(
                submitter,
                delivery.operation_id,
                finalized_cursor,
            ) {
                Some(true) => scan.dead_lettered = scan.dead_lettered.saturating_add(1),
                Some(false) | None => scan.deferred = scan.deferred.saturating_add(1),
            }
            continue;
        }
        if policy_status == AppealFinanceOutboxPolicyStatusV1::Superseded
            && matches!(
                delivery.state,
                AppealFinanceTransactionDeliveryStateV1::Ready
                    | AppealFinanceTransactionDeliveryStateV1::Signing
                    | AppealFinanceTransactionDeliveryStateV1::Signed
            )
        {
            if submitter
                .forwarder
                .mark_policy_superseded(delivery.operation_id, finalized_cursor)
                .is_ok()
            {
                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
            } else {
                scan.deferred = scan.deferred.saturating_add(1);
            }
            continue;
        }

        match delivery.state {
            AppealFinanceTransactionDeliveryStateV1::Ready => {
                let signer = match submitter.signer_for(&request.authority, finalized_cursor.height)
                {
                    Ok(signer) => signer,
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NotYetActive) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NoActiveBinding) => {
                        if submitter
                            .forwarder
                            .mark_signer_binding_inactive(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                        continue;
                    }
                    Err(
                        crate::SoraFsAppealFinanceSignerSelectionError::ProviderMissing
                        | crate::SoraFsAppealFinanceSignerSelectionError::IdentityMismatch,
                    ) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                };
                let claimed = match submitter
                    .forwarder
                    .claim_for_signing(delivery.operation_id, finalized_cursor)
                {
                    Ok(claimed) => claimed,
                    Err(_) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                };
                let signed = sign_sorafs_appeal_finance_delivery(state, signer, &claimed).await;
                let Some(bytes) = signed else {
                    match mark_appeal_finance_signing_failed(
                        submitter,
                        delivery.operation_id,
                        finalized_cursor,
                    ) {
                        Some(true) => {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        }
                        Some(false) | None => {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                    }
                    continue;
                };
                if submitter
                    .forwarder
                    .store_signed_transaction(delivery.operation_id, &bytes)
                    .is_err()
                {
                    match mark_appeal_finance_signing_failed(
                        submitter,
                        delivery.operation_id,
                        finalized_cursor,
                    ) {
                        Some(true) => {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        }
                        Some(false) | None => {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                    }
                    continue;
                }
                scan.signed = scan.signed.saturating_add(1);
                match submit_sorafs_appeal_finance_delivery(
                    state,
                    submitter,
                    delivery.operation_id,
                    &bytes,
                    finalized_cursor,
                )
                .await
                {
                    AppealFinanceDeliverySubmitOutcomeV1::Submitted => {
                        scan.submitted = scan.submitted.saturating_add(1);
                    }
                    AppealFinanceDeliverySubmitOutcomeV1::Deferred => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    AppealFinanceDeliverySubmitOutcomeV1::DeadLettered => {
                        scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                    }
                }
            }
            AppealFinanceTransactionDeliveryStateV1::Signed => {
                let Some(bytes) = delivery.signed_transaction_bytes.as_deref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match submitter.active_binding_for(&request.authority, finalized_cursor.height) {
                    Ok(_) => {}
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NotYetActive) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NoActiveBinding) => {
                        if submitter
                            .forwarder
                            .mark_signer_binding_inactive(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                        continue;
                    }
                    Err(
                        crate::SoraFsAppealFinanceSignerSelectionError::ProviderMissing
                        | crate::SoraFsAppealFinanceSignerSelectionError::IdentityMismatch,
                    ) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                }
                match submit_sorafs_appeal_finance_delivery(
                    state,
                    submitter,
                    delivery.operation_id,
                    bytes,
                    finalized_cursor,
                )
                .await
                {
                    AppealFinanceDeliverySubmitOutcomeV1::Submitted => {
                        scan.submitted = scan.submitted.saturating_add(1);
                    }
                    AppealFinanceDeliverySubmitOutcomeV1::Deferred => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    AppealFinanceDeliverySubmitOutcomeV1::DeadLettered => {
                        scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                    }
                }
            }
            AppealFinanceTransactionDeliveryStateV1::Ambiguous
            | AppealFinanceTransactionDeliveryStateV1::Submitted => {
                let Some(transaction) = signed_transaction.as_ref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let hash = transaction.hash();
                let local_pending = state
                    .queue
                    .contains_pending_hash(hash.clone(), &state.state);
                let cache_kind =
                    crate::pipeline_status_local_entry(state, &hash).map(|(entry, _)| entry.kind);
                match transaction_outcome {
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Rejected) => {
                        match mark_appeal_finance_transaction_rejected(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Some(
                        AppealFinanceAuthoritativeTransactionOutcomeV1::Applied { .. }
                        | AppealFinanceAuthoritativeTransactionOutcomeV1::Unavailable,
                    )
                    | None => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Absent)
                        if matches!(
                            cache_kind,
                            Some(
                                crate::PipelineStatusKind::Rejected
                                    | crate::PipelineStatusKind::Expired
                            )
                        ) =>
                    {
                        match mark_appeal_finance_transaction_rejected(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Absent)
                        if local_pending
                            || matches!(
                                cache_kind,
                                Some(
                                    crate::PipelineStatusKind::Queued
                                        | crate::PipelineStatusKind::Approved
                                        | crate::PipelineStatusKind::Committed
                                        | crate::PipelineStatusKind::Applied
                                )
                            ) =>
                    {
                        if delivery.state == AppealFinanceTransactionDeliveryStateV1::Ambiguous {
                            let _ = submitter.forwarder.mark_submitted(delivery.operation_id);
                        }
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Absent)
                        if finalized_cursor.height > delivery.baseline_finalized_height =>
                    {
                        match mark_appeal_finance_finalized_absent(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Some(AppealFinanceAuthoritativeTransactionOutcomeV1::Absent) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                }
            }
            AppealFinanceTransactionDeliveryStateV1::Signing => {
                match submitter.active_binding_for(&request.authority, finalized_cursor.height) {
                    Ok(_) => {
                        match mark_appeal_finance_signing_failed(
                            submitter,
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Some(true) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Some(false) | None => {
                                scan.deferred = scan.deferred.saturating_add(1);
                            }
                        }
                    }
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NotYetActive) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    Err(crate::SoraFsAppealFinanceSignerSelectionError::NoActiveBinding) => {
                        if submitter
                            .forwarder
                            .mark_signer_binding_inactive(delivery.operation_id, finalized_cursor)
                            .is_ok()
                        {
                            scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        } else {
                            scan.deferred = scan.deferred.saturating_add(1);
                        }
                    }
                    Err(
                        crate::SoraFsAppealFinanceSignerSelectionError::ProviderMissing
                        | crate::SoraFsAppealFinanceSignerSelectionError::IdentityMismatch,
                    ) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                }
            }
        }
    }
    scan
}

fn appeal_finance_operation_is_terminal(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
) -> Option<bool> {
    use sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarderError;

    match submitter
        .forwarder
        .operation_for_reconciliation(operation_id)
    {
        Ok(_) => Some(false),
        Err(AppealFinanceTransactionForwarderError::UnknownOperation) => Some(true),
        Err(_) => None,
    }
}

fn mark_appeal_finance_transaction_rejected(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> Option<bool> {
    submitter
        .forwarder
        .mark_transaction_rejected(operation_id, finalized_cursor)
        .ok()?;
    appeal_finance_operation_is_terminal(submitter, operation_id)
}

fn mark_appeal_finance_signing_failed(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> Option<bool> {
    submitter
        .forwarder
        .mark_signing_failed(operation_id, finalized_cursor)
        .ok()?;
    appeal_finance_operation_is_terminal(submitter, operation_id)
}

fn mark_appeal_finance_finalized_absent(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> Option<bool> {
    submitter
        .forwarder
        .mark_finalized_absent(operation_id, finalized_cursor)
        .ok()?;
    appeal_finance_operation_is_terminal(submitter, operation_id)
}

fn mark_appeal_finance_retryable_submission_failed(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> AppealFinanceDeliverySubmitOutcomeV1 {
    if submitter
        .forwarder
        .mark_retryable_submission_failed(operation_id, finalized_cursor)
        .is_err()
    {
        return AppealFinanceDeliverySubmitOutcomeV1::Deferred;
    }
    if appeal_finance_operation_is_terminal(submitter, operation_id) == Some(true) {
        AppealFinanceDeliverySubmitOutcomeV1::DeadLettered
    } else {
        AppealFinanceDeliverySubmitOutcomeV1::Deferred
    }
}

fn appeal_finance_exact_applied_post_record(
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
    applied_block_timestamp_ms: u64,
) -> Option<AssetEscrowRecord> {
    use sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1;

    let mut record = request.expected_record.clone()?;
    match &request.operation {
        AppealFinanceOperationV1::Open(_) => return None,
        AppealFinanceOperationV1::Drawdown(instruction) => {
            if record.id != *instruction.escrow_id()
                || record.remaining_amount != *instruction.expected_remaining_amount()
            {
                return None;
            }
            record.remaining_amount = record
                .remaining_amount
                .checked_sub(instruction.amount())
                .ok()?;
            if record.remaining_amount.is_zero() {
                record.status = AssetEscrowStatus::DrawnDown;
                record.closed_at_ms = Some(applied_block_timestamp_ms);
            }
        }
        AppealFinanceOperationV1::Cancel(instruction) => {
            if record.id != *instruction.escrow_id() {
                return None;
            }
            if record.remaining_amount != *instruction.expected_remaining_amount() {
                return None;
            }
            record.status = AssetEscrowStatus::Cancelled;
            record.remaining_amount = Quantity::zero();
            record.closed_at_ms = Some(applied_block_timestamp_ms);
        }
    }
    Some(record)
}

async fn sign_sorafs_appeal_finance_delivery(
    state: &SharedAppState,
    signer: Arc<dyn crate::SoraFsAppealFinanceTransactionSigner>,
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
) -> Option<Vec<u8>> {
    if AccountId::new(signer.public_key()) != request.authority {
        return None;
    }
    let mut builder = TransactionBuilder::new(
        request.chain_id.clone(),
        request.authority.clone(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    )
    .with_instructions([InstructionBox::from(request.operation.clone())]);
    builder.set_ttl(Duration::from_secs(300));
    let mut payload = builder.into_payload().ok()?;
    payload.fee_payment = crate::quote_internal_fee_payment(state, &payload).ok()?;
    let expected_payload = payload.clone();
    let transaction = tokio::task::spawn_blocking(move || signer.sign(payload))
        .await
        .ok()?
        .ok()?;
    if transaction.payload() != &expected_payload
        || transaction.authority() != &request.authority
        || transaction.verify_signature().is_err()
    {
        return None;
    }
    norito::to_bytes(&transaction).ok()
}

fn decode_appeal_finance_signed_transaction(bytes: &[u8]) -> Option<SignedTransaction> {
    let max_bytes = sorafs_node::appeal_finance_transaction_forwarder::
        APPEAL_FINANCE_TRANSACTION_MAX_CANONICAL_BYTES_V1;
    if bytes.is_empty() || bytes.len() > max_bytes {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let limits = norito::DecodeLimits::new(
        max_bytes,
        max_bytes,
        bytes.len().checked_mul(8)?,
        bytes.len().checked_mul(20)?.checked_add(512 * 1024)?,
        128,
    );
    let transaction =
        norito::decode_from_bytes_with_limits::<SignedTransaction>(bytes, limits).ok()?;
    (transaction.verify_signature().is_ok()
        && norito::to_bytes(&transaction).ok().as_deref() == Some(bytes))
    .then_some(transaction)
}

async fn submit_sorafs_appeal_finance_delivery(
    state: &SharedAppState,
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    operation_id: [u8; 32],
    transaction_bytes: &[u8],
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
) -> AppealFinanceDeliverySubmitOutcomeV1 {
    let Some(transaction) = decode_appeal_finance_signed_transaction(transaction_bytes) else {
        return AppealFinanceDeliverySubmitOutcomeV1::Deferred;
    };
    let accepted = match crate::routing::accept_transaction_for_ingress(
        state.chain_id.clone(),
        state.state.clone(),
        transaction.clone(),
        &state.telemetry,
    ) {
        Ok(accepted) => accepted,
        Err(_) => {
            return match mark_appeal_finance_transaction_rejected(
                submitter,
                operation_id,
                finalized_cursor,
            ) {
                Some(true) => AppealFinanceDeliverySubmitOutcomeV1::DeadLettered,
                Some(false) | None => AppealFinanceDeliverySubmitOutcomeV1::Deferred,
            };
        }
    };
    let durable_retry_claim = match state
        .queue
        .durable_plan_admission_claim_with_state(&accepted, state.state.as_ref())
    {
        Ok(claim) => claim,
        Err(_) => {
            return mark_appeal_finance_retryable_submission_failed(
                submitter,
                operation_id,
                finalized_cursor,
            );
        }
    };
    let routing_plan = if let Some(claim) = durable_retry_claim.as_ref() {
        claim.routing_plan.clone()
    } else {
        match state
            .queue
            .route_plan_with_state(&accepted, state.state.as_ref())
        {
            Ok(plan) => plan,
            Err(_) => {
                return mark_appeal_finance_retryable_submission_failed(
                    submitter,
                    operation_id,
                    finalized_cursor,
                );
            }
        }
    };
    let routing_decision = routing_plan.coordinator_route();
    let exact_bytes = match submitter.forwarder.begin_submission(operation_id) {
        Ok(bytes) => bytes,
        Err(_) => return AppealFinanceDeliverySubmitOutcomeV1::Deferred,
    };
    if exact_bytes != transaction_bytes {
        let _ = submitter.forwarder.mark_not_submitted(operation_id);
        return AppealFinanceDeliverySubmitOutcomeV1::Deferred;
    }
    let disposition = if crate::should_execute_route_locally(state.as_ref(), routing_decision) {
        match crate::routing::push_accepted_transaction_for_ingress_with_routing_plan_strict_durable(
            state.queue.clone(),
            state.state.clone(),
            accepted,
            routing_plan,
        ) {
            Ok(_) => AppealFinanceSubmissionDispositionV1::Submitted,
            Err(crate::Error::PushIntoQueue { source, .. }) => {
                classify_local_appeal_finance_submission(source.as_ref())
            }
            Err(_) => AppealFinanceSubmissionDispositionV1::Ambiguous,
        }
    } else {
        let response = crate::execute_torii_transaction_via_proxy(
            state,
            transaction.into(),
            routing_plan,
            durable_retry_claim,
            true,
            crate::utils::ResponseFormat::Norito,
        )
        .await;
        if response.status() == StatusCode::ACCEPTED {
            AppealFinanceSubmissionDispositionV1::Submitted
        } else {
            AppealFinanceSubmissionDispositionV1::Ambiguous
        }
    };
    match disposition {
        AppealFinanceSubmissionDispositionV1::Submitted => {
            if submitter.forwarder.mark_submitted(operation_id).is_ok() {
                AppealFinanceDeliverySubmitOutcomeV1::Submitted
            } else {
                AppealFinanceDeliverySubmitOutcomeV1::Deferred
            }
        }
        AppealFinanceSubmissionDispositionV1::DefinitelyNotSubmitted => {
            mark_appeal_finance_retryable_submission_failed(
                submitter,
                operation_id,
                finalized_cursor,
            )
        }
        AppealFinanceSubmissionDispositionV1::Rejected => {
            match mark_appeal_finance_transaction_rejected(
                submitter,
                operation_id,
                finalized_cursor,
            ) {
                Some(true) => AppealFinanceDeliverySubmitOutcomeV1::DeadLettered,
                Some(false) | None => AppealFinanceDeliverySubmitOutcomeV1::Deferred,
            }
        }
        AppealFinanceSubmissionDispositionV1::Ambiguous => {
            AppealFinanceDeliverySubmitOutcomeV1::Deferred
        }
    }
}

fn decode_appeal_finance_outbox_context(
    bytes: &[u8],
) -> Option<AppealFinanceSettlementOutboxContextV1> {
    let max_bytes = sorafs_node::appeal_finance_transaction_forwarder::
        APPEAL_FINANCE_RECONCILIATION_CONTEXT_MAX_BYTES_V1;
    if bytes.is_empty() || bytes.len() > max_bytes {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let limits = norito::DecodeLimits::new(
        max_bytes,
        max_bytes,
        bytes.len().checked_mul(8)?,
        bytes.len().checked_mul(20)?.checked_add(256 * 1024)?,
        64,
    );
    let context = norito::decode_from_bytes_with_limits::<AppealFinanceSettlementOutboxContextV1>(
        bytes, limits,
    )
    .ok()?;
    if context.version != APPEAL_FINANCE_SETTLEMENT_OUTBOX_CONTEXT_VERSION_V1
        || context.policy_digest == [0; 32]
        || context.panel_size == 0
        || !appeal_finance_deposit_expectation_is_canonical(&context.expected)
        || context.settlement.asset_scale
            != iroha_config::parameters::defaults::torii::sorafs_appeal_finance::ASSET_SCALE
        || !is_canonical_appeal_finance_policy_version(&context.settlement.config_version)
        || appeal_verdict_from_request(&context.outcome)
            .ok()
            .map(|verdict| verdict.to_string())
            .as_deref()
            != Some(context.outcome.as_str())
        || norito::to_bytes(&context).ok().as_deref() != Some(bytes)
    {
        return None;
    }
    let deposit = XorQuantity::try_from_quantity(context.expected.deposit_xor.clone()).ok()?;
    let refund = XorQuantity::try_from_quantity(context.settlement.refund_xor.clone()).ok()?;
    let treasury = XorQuantity::try_from_quantity(context.settlement.treasury_xor.clone()).ok()?;
    let held = XorQuantity::try_from_quantity(context.settlement.held_xor.clone()).ok()?;
    let panel_reward_per_juror =
        XorQuantity::try_from_quantity(context.settlement.panel_reward_per_juror_xor.clone())
            .ok()?;
    let panel_reward_total =
        XorQuantity::try_from_quantity(context.settlement.panel_reward_total_xor.clone()).ok()?;
    let accounted = refund
        .checked_add(&treasury)
        .ok()?
        .checked_add(&held)
        .ok()?;
    let minimum_panel_reward = panel_reward_per_juror
        .checked_mul_u64(u64::from(context.panel_size))
        .ok()?;
    (!deposit.is_zero() && accounted == deposit && panel_reward_total >= minimum_panel_reward)
        .then_some(context)
}

fn decode_appeal_finance_deposit_outbox_context(
    bytes: &[u8],
) -> Option<AppealFinanceDepositOutboxContextV1> {
    let max_bytes = sorafs_node::appeal_finance_transaction_forwarder::
        APPEAL_FINANCE_RECONCILIATION_CONTEXT_MAX_BYTES_V1;
    if bytes.is_empty() || bytes.len() > max_bytes {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let limits = norito::DecodeLimits::new(
        max_bytes,
        max_bytes,
        bytes.len().checked_mul(8)?,
        bytes.len().checked_mul(20)?.checked_add(256 * 1024)?,
        64,
    );
    let context =
        norito::decode_from_bytes_with_limits::<AppealFinanceDepositOutboxContextV1>(bytes, limits)
            .ok()?;
    (context.version == APPEAL_FINANCE_DEPOSIT_OUTBOX_CONTEXT_VERSION_V1
        && context.policy_digest != [0; 32]
        && appeal_finance_deposit_expectation_is_canonical(&context.expected)
        && norito::to_bytes(&context).ok().as_deref() == Some(bytes))
    .then_some(context)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AppealFinanceOutboxPolicyStatusV1 {
    Active,
    Grandfathered,
    Superseded,
    InvalidContext,
}

fn appeal_finance_outbox_policy_status(
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
    policy: &AppealFinanceRuntimePolicy,
) -> AppealFinanceOutboxPolicyStatusV1 {
    use sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1;

    let (policy_digest, expected, grandfathered_continuation) = match &request.operation {
        AppealFinanceOperationV1::Open(instruction) => {
            let Some(context) =
                decode_appeal_finance_deposit_outbox_context(&request.reconciliation_context)
            else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            if request.authority != context.expected.payer_account
                || instruction.asset_definition() != &context.expected.asset_definition_id
                || instruction.destination() != &context.expected.destination_account
                || instruction.amount() != &context.expected.deposit_xor
                || instruction.release_authority().as_ref()
                    != context.expected.release_authority_account.as_ref()
                || *instruction.expires_at_ms() != context.expected.expires_at_ms
                || instruction.evidence_hashes().as_slice()
                    != context.expected.evidence_hashes.as_slice()
            {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            }
            (context.policy_digest, context.expected, false)
        }
        AppealFinanceOperationV1::Drawdown(instruction) => {
            let Some(context) =
                decode_appeal_finance_outbox_context(&request.reconciliation_context)
            else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            let Some(record) = request.expected_record.as_ref() else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            let Ok(drawdown_xor) = context
                .settlement
                .treasury_xor
                .checked_add(&context.settlement.held_xor)
            else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            let required_authority = context
                .expected
                .release_authority_account
                .as_ref()
                .unwrap_or(&context.expected.destination_account);
            if drawdown_xor.is_zero()
                || instruction.amount() != &drawdown_xor
                || instruction.expected_remaining_amount() != &record.remaining_amount
                || record.remaining_amount != context.expected.deposit_xor
                || &request.authority != required_authority
                || !appeal_finance_locked_record_matches_expectation(&context.expected, record)
            {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            }
            (context.policy_digest, context.expected, false)
        }
        AppealFinanceOperationV1::Cancel(instruction) => {
            let Some(context) =
                decode_appeal_finance_outbox_context(&request.reconciliation_context)
            else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            let Some(record) = request.expected_record.as_ref() else {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            };
            if context.settlement.refund_xor.is_zero()
                || &request.authority != &context.expected.payer_account
                || record.remaining_amount != context.settlement.refund_xor
                || record.id != *instruction.escrow_id()
                || record.remaining_amount != *instruction.expected_remaining_amount()
                || !appeal_finance_locked_record_matches_expectation(&context.expected, record)
            {
                return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
            }
            (context.policy_digest, context.expected, true)
        }
    };
    if expected.escrow_id != *request.operation.escrow_id()
        || XorQuantity::try_from_quantity(expected.deposit_xor).is_err()
    {
        return AppealFinanceOutboxPolicyStatusV1::InvalidContext;
    }
    if policy_digest == policy.policy_digest {
        if expected.asset_definition_id == policy.asset_definition_id {
            AppealFinanceOutboxPolicyStatusV1::Active
        } else {
            AppealFinanceOutboxPolicyStatusV1::InvalidContext
        }
    } else if grandfathered_continuation {
        AppealFinanceOutboxPolicyStatusV1::Grandfathered
    } else {
        AppealFinanceOutboxPolicyStatusV1::Superseded
    }
}

fn appeal_finance_locked_record_matches_expectation(
    expected: &AppealFinanceDepositExpectation,
    record: &AssetEscrowRecord,
) -> bool {
    record.kind == AssetEscrowKind::Lock
        && record.status == AssetEscrowStatus::Locked
        && !record.remaining_amount.is_zero()
        && record.accepted_at_ms.is_none()
        && record.payment_sent_at_ms.is_none()
        && record.disputed_at_ms.is_none()
        && record.closed_at_ms.is_none()
        && record.resolution.is_none()
        && appeal_finance_deposit_static_mismatches(expected, record).is_empty()
}

fn appeal_finance_step_for_operation<'a>(
    operation: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1,
    execution: &'a AppealFinanceDepositSettlementExecution,
) -> Option<&'a AppealFinanceSettlementStep> {
    match operation {
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Open(_) => {
            None
        }
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Drawdown(
            _,
        ) => execution
            .steps
            .iter()
            .find(|step| step.action == "drawdown_non_refund"),
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Cancel(_) => {
            execution
                .steps
                .iter()
                .find(|step| step.action == "cancel_refund")
        }
    }
}

fn publish_finalized_appeal_finance_receipt(
    state: &SharedAppState,
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
    delivery: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionPendingV1,
    finalized_block_height: u64,
    finalized_block_hash: [u8; 32],
    record: &AssetEscrowRecord,
) -> bool {
    if !state.sorafs_node.has_governance_publisher() {
        return false;
    }
    let Some(context) = decode_appeal_finance_outbox_context(&request.reconciliation_context)
    else {
        return false;
    };
    if context.expected.escrow_id != *request.operation.escrow_id() {
        return false;
    }
    let Ok(verdict) = appeal_verdict_from_request(&context.outcome) else {
        return false;
    };
    let breakdown = context.settlement.breakdown();
    let Ok(reconciliation) = appeal_finance_deposit_settlement_reconciliation_with_policy_binding(
        &context.expected,
        record,
        context.policy_digest,
        &context.settlement.config_version,
        context.settlement.asset_scale,
        verdict,
        context.panel_size,
        &breakdown,
    ) else {
        return false;
    };
    let Ok(execution) =
        appeal_finance_deposit_settlement_execution(&context.expected, record, &breakdown)
    else {
        return false;
    };
    let Some(step) = appeal_finance_step_for_operation(&request.operation, &execution) else {
        return false;
    };
    let Some(transaction) = delivery
        .signed_transaction_bytes
        .as_deref()
        .and_then(decode_appeal_finance_signed_transaction)
    else {
        return false;
    };
    let tx_hash_hex = hex::encode(transaction.hash().as_ref());
    let generated_at_unix_ms =
        u64::try_from(transaction.creation_time().as_millis()).unwrap_or(u64::MAX);
    if generated_at_unix_ms == 0 {
        return false;
    }
    let Ok(receipt) = appeal_finance_deposit_settlement_receipt(
        context.policy_digest,
        &context.settlement.config_version,
        &context.expected,
        record,
        verdict,
        context.panel_size,
        &breakdown,
        &reconciliation,
        step,
        &tx_hash_hex,
        finalized_block_height,
        finalized_block_hash,
        submitter.signer_count(request.baseline_finalized_cursor.height),
        generated_at_unix_ms,
    ) else {
        return false;
    };
    state
        .sorafs_node
        .publish_appeal_finance_settlement_receipt(receipt)
        .is_ok()
}

fn enqueue_appeal_finance_followup(
    submitter: &crate::SoraFsAppealSettlementSubmitter,
    request: &sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1,
    finalized_cursor: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceFinalizedCursorV1,
    record: &AssetEscrowRecord,
) -> Option<bool> {
    use sorafs_node::appeal_finance_transaction_forwarder::{
        AppealFinanceOperationV1, AppealFinanceTransactionContextV1,
    };
    if !matches!(request.operation, AppealFinanceOperationV1::Drawdown(_)) {
        return Some(false);
    }
    let Some(context) = decode_appeal_finance_outbox_context(&request.reconciliation_context)
    else {
        return None;
    };
    let Ok(verdict) = appeal_verdict_from_request(&context.outcome) else {
        return None;
    };
    let breakdown = context.settlement.breakdown();
    let Ok(reconciliation) = appeal_finance_deposit_settlement_reconciliation_with_policy_binding(
        &context.expected,
        record,
        context.policy_digest,
        &context.settlement.config_version,
        context.settlement.asset_scale,
        verdict,
        context.panel_size,
        &breakdown,
    ) else {
        return None;
    };
    let Ok(execution) =
        appeal_finance_deposit_settlement_execution(&context.expected, record, &breakdown)
    else {
        return None;
    };
    let Some(step) =
        appeal_finance_deposit_next_settlement_submission_step(&reconciliation, &execution)
    else {
        return Some(false);
    };
    if step.action != "cancel_refund" {
        return None;
    }
    submitter
        .forwarder
        .enqueue_unsigned_operation(
            step.required_authority.clone(),
            AppealFinanceOperationV1::Cancel(CancelAssetLock::new(
                context.expected.escrow_id,
                record.remaining_amount.clone(),
            )),
            &AppealFinanceTransactionContextV1 {
                chain_id: request.chain_id.clone(),
                finalized_cursor,
                expected_record: Some(record.clone()),
                reconciliation_context: request.reconciliation_context.clone(),
            },
        )
        .ok()
        .map(|_| true)
}

const SORAFS_PROOF_OUTCOME_FORWARDER_SCAN_LIMIT_V1: usize = 256;

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsProofOutcomeForwarderScanV1 {
    scanned: usize,
    finalized: usize,
    signed: usize,
    submitted: usize,
    deferred: usize,
    unauthorized_signer: usize,
    dead_lettered: usize,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsProofOutcomeForwarderCursorV1 {
    after_sequence: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ProofOutcomeSubmissionDispositionV1 {
    Submitted,
    DefinitelyNotSubmitted,
    Rejected,
    Ambiguous,
}

fn classify_local_proof_outcome_submission(
    error: &iroha_core::queue::Error,
) -> ProofOutcomeSubmissionDispositionV1 {
    match error {
        iroha_core::queue::Error::InBlockchain | iroha_core::queue::Error::IsInQueue => {
            ProofOutcomeSubmissionDispositionV1::Submitted
        }
        iroha_core::queue::Error::PlanJournalDurabilityIndeterminate { .. } => {
            ProofOutcomeSubmissionDispositionV1::Ambiguous
        }
        iroha_core::queue::Error::Expired => ProofOutcomeSubmissionDispositionV1::Rejected,
        _ => ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted,
    }
}

#[cfg(test)]
mod proof_outcome_submission_disposition_tests {
    use super::*;

    #[test]
    fn local_queue_dispositions_preserve_definite_and_ambiguous_boundaries() {
        assert_eq!(
            classify_local_proof_outcome_submission(&iroha_core::queue::Error::Full),
            ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted
        );
        assert_eq!(
            classify_local_proof_outcome_submission(
                &iroha_core::queue::Error::PlanJournalDurabilityRejected {
                    reason: "unavailable".to_owned(),
                }
            ),
            ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted
        );
        assert_eq!(
            classify_local_proof_outcome_submission(
                &iroha_core::queue::Error::PlanJournalDurabilityIndeterminate {
                    transaction_hash: iroha_crypto::HashOf::from_untyped_unchecked(
                        iroha_crypto::Hash::prehashed([0xA5; 32]),
                    ),
                    reason: "unknown".to_owned(),
                }
            ),
            ProofOutcomeSubmissionDispositionV1::Ambiguous
        );
        assert_eq!(
            classify_local_proof_outcome_submission(&iroha_core::queue::Error::IsInQueue),
            ProofOutcomeSubmissionDispositionV1::Submitted
        );
        assert_eq!(
            classify_local_proof_outcome_submission(&iroha_core::queue::Error::Expired),
            ProofOutcomeSubmissionDispositionV1::Rejected
        );
    }
}

fn proof_outcome_authority_has_provider_permission(
    world: &impl WorldReadOnly,
    authority: &AccountId,
    provider_id: ProviderId,
) -> bool {
    let required = Permission::from(CanRecordSorafsProofOutcome { provider_id });
    crate::torii_account_has_permission(world, authority, &required)
}

pub(crate) fn spawn_sorafs_proof_outcome_forwarder_worker(
    state: SharedAppState,
    shutdown_signal: ShutdownSignal,
) {
    if !state.sorafs_node.is_enabled() {
        debug!("SoraFS proof-outcome forwarder disabled: SoraFS storage is disabled");
        return;
    }
    if state.sorafs_proof_outcome_signer.is_none() {
        warn!(
            "SoraFS proof-outcome forwarder has no runtime signer; finalized reconciliation remains active"
        );
    }
    let worker_interval = state
        .sorafs_node
        .config()
        .runtime_retention()
        .proof_outcome_forwarder_interval();

    tokio::spawn(async move {
        let mut interval = tokio::time::interval(worker_interval);
        let mut cursor = SorafsProofOutcomeForwarderCursorV1::default();
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
        loop {
            tokio::select! {
                () = shutdown_signal.receive() => break,
                _ = interval.tick() => {
                    let scan = run_sorafs_proof_outcome_forwarder_scan(&state, &mut cursor).await;
                    if scan.scanned != 0 {
                        debug!(
                            scanned = scan.scanned,
                            finalized = scan.finalized,
                            signed = scan.signed,
                            submitted = scan.submitted,
                            deferred = scan.deferred,
                            unauthorized_signer = scan.unauthorized_signer,
                            dead_lettered = scan.dead_lettered,
                            "processed durable SoraFS proof-outcome deliveries"
                        );
                    }
                }
            }
        }
    });
}

pub(crate) async fn run_sorafs_proof_outcome_forwarder_scan(
    state: &SharedAppState,
    cursor: &mut SorafsProofOutcomeForwarderCursorV1,
) -> SorafsProofOutcomeForwarderScanV1 {
    let mut scan = SorafsProofOutcomeForwarderScanV1::default();
    let pending = match state.sorafs_node.pending_proof_outcome_deliveries_after(
        cursor.after_sequence,
        SORAFS_PROOF_OUTCOME_FORWARDER_SCAN_LIMIT_V1,
    ) {
        Ok(pending) => pending,
        Err(_) => {
            warn!("failed to load durable SoraFS proof-outcome deliveries");
            return scan;
        }
    };
    for delivery in pending {
        cursor.after_sequence = Some(delivery.sequence);
        scan.scanned = scan.scanned.saturating_add(1);
        let reconciliation = {
            let view = state.state.query_view();
            u64::try_from(view.block_hashes.len())
                .ok()
                .zip(view.block_hashes.last())
                .map(|(height, hash)| ProofOutcomeFinalizedCursorV1 {
                    height,
                    block_hash: *hash.as_ref(),
                })
                .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
                .map(|cursor| {
                    let finalized =
                        FindSorafsProofOutcome::new(delivery.kind, delivery.identity_digest, None)
                            .execute(&view);
                    (cursor, finalized)
                })
        };
        let Some((finalized_cursor, finalized)) = reconciliation else {
            scan.deferred = scan.deferred.saturating_add(1);
            continue;
        };
        match finalized {
            Ok(finalized) => {
                match state
                    .sorafs_node
                    .mark_proof_outcome_finalized(delivery.operation_id, &finalized)
                {
                    Ok(()) => scan.finalized = scan.finalized.saturating_add(1),
                    Err(sorafs_node::ProofOutcomeOutboxError::FinalizedConflict) => {
                        scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                        warn!(
                            proof_kind = ?delivery.kind,
                            "finalized SoraFS proof outcome conflicts with the durable delivery"
                        );
                    }
                    Err(_) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        warn!("failed to checkpoint finalized SoraFS proof outcome");
                    }
                }
                continue;
            }
            Err(QueryExecutionFail::Find(FindError::SorafsProofOutcome(_))) => {}
            Err(_) => {
                scan.deferred = scan.deferred.saturating_add(1);
                warn!("authoritative SoraFS proof-outcome reconciliation query failed");
                continue;
            }
        }

        match delivery.state {
            sorafs_node::ProofOutcomeDeliveryStateV1::Ready => {
                let Some(signer) = state.sorafs_proof_outcome_signer.clone() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let signer_is_authorized = {
                    let view = state.state.query_view();
                    proof_outcome_authority_has_provider_permission(
                        view.world(),
                        &signer.authority(),
                        delivery.provider_id,
                    )
                };
                if !signer_is_authorized {
                    scan.deferred = scan.deferred.saturating_add(1);
                    scan.unauthorized_signer = scan.unauthorized_signer.saturating_add(1);
                    warn!(
                        proof_kind = ?delivery.kind,
                        "SoraFS proof-outcome runtime signer lacks the finalized provider-scoped permission"
                    );
                    continue;
                }
                let claimed = match state
                    .sorafs_node
                    .claim_proof_outcome_for_signing(delivery.operation_id, finalized_cursor)
                {
                    Ok(claimed) => claimed,
                    Err(_) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                };
                let Some(transaction) =
                    sign_sorafs_proof_outcome_delivery(state, signer, &claimed).await
                else {
                    let _ = state
                        .sorafs_node
                        .release_proof_outcome_signing_claim(delivery.operation_id);
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match state.sorafs_node.store_signed_proof_outcome_transaction(
                    delivery.operation_id,
                    transaction.clone(),
                ) {
                    Ok(_) => scan.signed = scan.signed.saturating_add(1),
                    Err(_) => {
                        let _ = state
                            .sorafs_node
                            .release_proof_outcome_signing_claim(delivery.operation_id);
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                }
                if submit_sorafs_proof_outcome_delivery(state, delivery.operation_id, transaction)
                    .await
                {
                    scan.submitted = scan.submitted.saturating_add(1);
                } else {
                    scan.deferred = scan.deferred.saturating_add(1);
                }
            }
            sorafs_node::ProofOutcomeDeliveryStateV1::Signed => {
                let Some(transaction) = delivery.signed_transaction else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                if submit_sorafs_proof_outcome_delivery(state, delivery.operation_id, transaction)
                    .await
                {
                    scan.submitted = scan.submitted.saturating_add(1);
                } else {
                    scan.deferred = scan.deferred.saturating_add(1);
                }
            }
            sorafs_node::ProofOutcomeDeliveryStateV1::Ambiguous
            | sorafs_node::ProofOutcomeDeliveryStateV1::Submitted => {
                let Some(transaction) = delivery.signed_transaction.as_ref() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match crate::pipeline_status_local_entry(state, &transaction.hash()) {
                    Some((entry, _))
                        if matches!(
                            entry.kind,
                            crate::PipelineStatusKind::Rejected
                                | crate::PipelineStatusKind::Expired
                        ) =>
                    {
                        match state.sorafs_node.mark_proof_outcome_transaction_rejected(
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Ok(()) => {
                                scan.dead_lettered = scan.dead_lettered.saturating_add(1);
                            }
                            Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                        }
                    }
                    Some((_entry, _)) => {
                        if delivery.state == sorafs_node::ProofOutcomeDeliveryStateV1::Ambiguous {
                            let _ = state
                                .sorafs_node
                                .mark_proof_outcome_submitted(delivery.operation_id);
                        }
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    None if finalized_cursor.height > delivery.baseline_finalized_height => {
                        match state.sorafs_node.mark_proof_outcome_finalized_absent(
                            delivery.operation_id,
                            finalized_cursor,
                        ) {
                            Ok(()) => scan.deferred = scan.deferred.saturating_add(1),
                            Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                        }
                    }
                    None => scan.deferred = scan.deferred.saturating_add(1),
                }
            }
            sorafs_node::ProofOutcomeDeliveryStateV1::Signing => {
                scan.deferred = scan.deferred.saturating_add(1);
            }
        }
    }
    scan
}

async fn sign_sorafs_proof_outcome_delivery(
    state: &SharedAppState,
    signer: Arc<dyn crate::SoraFsProofOutcomeTransactionSigner>,
    delivery: &sorafs_node::ProofOutcomePendingDeliveryV1,
) -> Option<SignedTransaction> {
    let mut builder = TransactionBuilder::new(
        (*state.chain_id).clone(),
        signer.authority(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    )
    .with_instructions([InstructionBox::from(SubmitSorafsProofOutcome::new(
        delivery.submission.clone(),
    ))]);
    builder.set_ttl(Duration::from_secs(300));
    let mut payload = builder.into_payload().ok()?;
    payload.fee_payment = crate::quote_internal_fee_payment(state, &payload).ok()?;
    let expected_payload = payload.clone();
    let transaction = tokio::task::spawn_blocking(move || signer.sign(payload))
        .await
        .ok()?
        .ok()?;
    (transaction.payload() == &expected_payload).then_some(transaction)
}

async fn submit_sorafs_proof_outcome_delivery(
    state: &SharedAppState,
    operation_id: [u8; 32],
    transaction: SignedTransaction,
) -> bool {
    let accepted = match crate::routing::accept_transaction_for_ingress(
        state.chain_id.clone(),
        state.state.clone(),
        transaction.clone(),
        &state.telemetry,
    ) {
        Ok(accepted) => accepted,
        Err(_) => {
            let finalized_cursor = {
                let view = state.state.query_view();
                u64::try_from(view.block_hashes.len())
                    .ok()
                    .zip(view.block_hashes.last())
                    .map(|(height, hash)| ProofOutcomeFinalizedCursorV1 {
                        height,
                        block_hash: *hash.as_ref(),
                    })
                    .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
            };
            if let Some(finalized_cursor) = finalized_cursor {
                let _ = state
                    .sorafs_node
                    .mark_proof_outcome_transaction_rejected(operation_id, finalized_cursor);
            }
            return false;
        }
    };
    let durable_retry_claim = match state
        .queue
        .durable_plan_admission_claim_with_state(&accepted, state.state.as_ref())
    {
        Ok(claim) => claim,
        Err(_) => return false,
    };
    let routing_plan = if let Some(claim) = durable_retry_claim.as_ref() {
        claim.routing_plan.clone()
    } else {
        match state
            .queue
            .route_plan_with_state(&accepted, state.state.as_ref())
        {
            Ok(plan) => plan,
            Err(_) => return false,
        }
    };
    let routing_decision = routing_plan.coordinator_route();
    let exact_transaction = match state
        .sorafs_node
        .begin_proof_outcome_submission(operation_id)
    {
        Ok(transaction) => transaction,
        Err(_) => return false,
    };
    if exact_transaction.hash() != transaction.hash() {
        let _ = state
            .sorafs_node
            .mark_proof_outcome_not_submitted(operation_id);
        return false;
    }

    let disposition = if crate::should_execute_route_locally(state.as_ref(), routing_decision) {
        match crate::routing::push_accepted_transaction_for_ingress_with_routing_plan_strict_durable(
            state.queue.clone(),
            state.state.clone(),
            accepted,
            routing_plan,
        ) {
            Ok(_) => ProofOutcomeSubmissionDispositionV1::Submitted,
            Err(crate::Error::PushIntoQueue { source, .. }) => {
                classify_local_proof_outcome_submission(source.as_ref())
            }
            Err(_) => ProofOutcomeSubmissionDispositionV1::Ambiguous,
        }
    } else {
        let response = crate::execute_torii_transaction_via_proxy(
            state,
            exact_transaction.into(),
            routing_plan,
            durable_retry_claim,
            true,
            crate::utils::ResponseFormat::Norito,
        )
        .await;
        if response.status() == StatusCode::ACCEPTED {
            ProofOutcomeSubmissionDispositionV1::Submitted
        } else {
            ProofOutcomeSubmissionDispositionV1::Ambiguous
        }
    };
    match disposition {
        ProofOutcomeSubmissionDispositionV1::Submitted => state
            .sorafs_node
            .mark_proof_outcome_submitted(operation_id)
            .is_ok(),
        ProofOutcomeSubmissionDispositionV1::DefinitelyNotSubmitted => {
            let _ = state
                .sorafs_node
                .mark_proof_outcome_not_submitted(operation_id);
            false
        }
        ProofOutcomeSubmissionDispositionV1::Rejected => {
            let finalized_cursor = {
                let view = state.state.query_view();
                u64::try_from(view.block_hashes.len())
                    .ok()
                    .zip(view.block_hashes.last())
                    .map(|(height, hash)| ProofOutcomeFinalizedCursorV1 {
                        height,
                        block_hash: *hash.as_ref(),
                    })
                    .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
            };
            if let Some(finalized_cursor) = finalized_cursor {
                let _ = state
                    .sorafs_node
                    .mark_proof_outcome_transaction_rejected(operation_id, finalized_cursor);
            }
            false
        }
        ProofOutcomeSubmissionDispositionV1::Ambiguous => false,
    }
}

const SORAFS_REPAIR_TRANSACTION_FORWARDER_SCAN_LIMIT_V1: usize = 256;
const SORAFS_NATIVE_REPAIR_TASK_SCAN_LIMIT_V1: u32 = 32;

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsRepairTransactionForwarderScanV1 {
    pdp_handoffs_resumed: usize,
    potr_handoffs_resumed: usize,
    task_scanned: usize,
    lease_enqueued: usize,
    terminal_enqueued: usize,
    scanned: usize,
    finalized: usize,
    signed: usize,
    submitted: usize,
    deferred: usize,
    unauthorized_signer: usize,
    conflicted: usize,
    rejected: usize,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SorafsRepairTransactionForwarderCursorV1 {
    after_sequence: Option<u64>,
    after_task_id: Option<[u8; 32]>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeRepairTaskDispositionV1 {
    Claim,
    Renew { lease_generation: u64 },
    Execute,
    Defer,
}

fn classify_native_repair_task(
    task: &RepairLedgerTaskV1,
    authority: &AccountId,
    now_unix_ms: u64,
    renew_before_ms: u64,
) -> NativeRepairTaskDispositionV1 {
    if now_unix_ms == 0 || task.revision == 0 || task.terminal_outcome.is_some() {
        return NativeRepairTaskDispositionV1::Defer;
    }
    let Some(lease) = task.lease.as_ref() else {
        return NativeRepairTaskDispositionV1::Claim;
    };
    if lease.expires_at_unix_ms <= now_unix_ms {
        return NativeRepairTaskDispositionV1::Claim;
    }
    if lease.generation == 0
        || &lease.owner != authority
        || lease.acquired_at_unix_ms == 0
        || lease.renewed_at_unix_ms < lease.acquired_at_unix_ms
        || lease.expires_at_unix_ms <= lease.renewed_at_unix_ms
    {
        return NativeRepairTaskDispositionV1::Defer;
    }
    if lease.expires_at_unix_ms.saturating_sub(now_unix_ms) <= renew_before_ms {
        NativeRepairTaskDispositionV1::Renew {
            lease_generation: lease.generation,
        }
    } else {
        NativeRepairTaskDispositionV1::Execute
    }
}

fn gate_native_repair_task_generation(
    enabled: bool,
    disposition: NativeRepairTaskDispositionV1,
) -> NativeRepairTaskDispositionV1 {
    if enabled {
        disposition
    } else {
        NativeRepairTaskDispositionV1::Defer
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairTransactionSubmissionDispositionV1 {
    Submitted,
    DefinitelyNotSubmitted,
    Rejected,
    Ambiguous,
}

fn classify_local_repair_transaction_submission(
    error: &iroha_core::queue::Error,
) -> RepairTransactionSubmissionDispositionV1 {
    match error {
        iroha_core::queue::Error::InBlockchain | iroha_core::queue::Error::IsInQueue => {
            RepairTransactionSubmissionDispositionV1::Submitted
        }
        iroha_core::queue::Error::PlanJournalDurabilityIndeterminate { .. } => {
            RepairTransactionSubmissionDispositionV1::Ambiguous
        }
        iroha_core::queue::Error::Expired => RepairTransactionSubmissionDispositionV1::Rejected,
        _ => RepairTransactionSubmissionDispositionV1::DefinitelyNotSubmitted,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairAuthorizationScopeV1 {
    Provider([u8; 32]),
    ProviderOwner([u8; 32]),
}

impl RepairAuthorizationScopeV1 {
    fn is_authorized(self, world: &impl WorldReadOnly, authority: &AccountId) -> bool {
        let provider_id = ProviderId::new(match self {
            Self::Provider(provider_id) | Self::ProviderOwner(provider_id) => provider_id,
        });
        match self {
            Self::Provider(_) => {
                let required = Permission::from(CanOperateSorafsRepair { provider_id });
                crate::torii_account_has_permission(world, authority, &required)
            }
            Self::ProviderOwner(_) => world
                .provider_owners()
                .get(&provider_id)
                .is_some_and(|owner| owner == authority),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairSemanticReconciliationV1 {
    Finalized(RepairFinalizedCursorV1),
    Ready(RepairAuthorizationScopeV1),
    Deferred,
    Conflict(RepairFinalizedCursorV1),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairTransactionReconciliationV1 {
    Finalized(RepairFinalizedCursorV1),
    Ready {
        finalized_cursor: RepairFinalizedCursorV1,
        authority_is_authorized: bool,
    },
    Deferred,
    Conflict(RepairFinalizedCursorV1),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairCommittedExternalOutcomeV1 {
    Applied,
    Rejected,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairAuthoritativeTransactionOutcomeV1 {
    Absent,
    Applied,
    Rejected,
    Unavailable,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairExactDeliveryDispositionV1 {
    Applied,
    Rejected,
    FinalizedAbsent,
    Pending,
    Unavailable,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RepairExactTransactionObservationV1 {
    reconciliation: RepairTransactionReconciliationV1,
    finalized_cursor: RepairFinalizedCursorV1,
    transaction_outcome: RepairAuthoritativeTransactionOutcomeV1,
}

fn classify_exact_repair_entrypoint_outcome(
    expected_hash: &HashOf<SignedTransaction>,
    block_available: bool,
    results: impl IntoIterator<Item = (HashOf<SignedTransaction>, RepairCommittedExternalOutcomeV1)>,
) -> RepairAuthoritativeTransactionOutcomeV1 {
    if !block_available {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    let mut exact = results
        .into_iter()
        .filter_map(|(hash, outcome)| (&hash == expected_hash).then_some(outcome));
    let Some(outcome) = exact.next() else {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    };
    if exact.next().is_some() {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    match outcome {
        RepairCommittedExternalOutcomeV1::Applied => {
            RepairAuthoritativeTransactionOutcomeV1::Applied
        }
        RepairCommittedExternalOutcomeV1::Rejected => {
            RepairAuthoritativeTransactionOutcomeV1::Rejected
        }
    }
}

fn local_repair_evidence_blocks_absence_retry(
    queue_pending: bool,
    cache_kind: Option<crate::PipelineStatusKind>,
) -> bool {
    queue_pending
        || matches!(
            cache_kind,
            Some(
                crate::PipelineStatusKind::Queued
                    | crate::PipelineStatusKind::Approved
                    | crate::PipelineStatusKind::Committed
                    | crate::PipelineStatusKind::Applied
            )
        )
}

fn classify_exact_repair_delivery(
    transaction_outcome: RepairAuthoritativeTransactionOutcomeV1,
    finalized_cursor: RepairFinalizedCursorV1,
    baseline_finalized_height: u64,
    local_evidence_blocks_absence_retry: bool,
) -> RepairExactDeliveryDispositionV1 {
    match transaction_outcome {
        RepairAuthoritativeTransactionOutcomeV1::Applied => {
            RepairExactDeliveryDispositionV1::Applied
        }
        RepairAuthoritativeTransactionOutcomeV1::Rejected => {
            RepairExactDeliveryDispositionV1::Rejected
        }
        RepairAuthoritativeTransactionOutcomeV1::Unavailable => {
            RepairExactDeliveryDispositionV1::Unavailable
        }
        RepairAuthoritativeTransactionOutcomeV1::Absent if local_evidence_blocks_absence_retry => {
            RepairExactDeliveryDispositionV1::Pending
        }
        RepairAuthoritativeTransactionOutcomeV1::Absent
            if finalized_cursor.height > baseline_finalized_height =>
        {
            RepairExactDeliveryDispositionV1::FinalizedAbsent
        }
        RepairAuthoritativeTransactionOutcomeV1::Absent => {
            RepairExactDeliveryDispositionV1::Unavailable
        }
    }
}

fn retained_repair_transaction_digest_for_finalization(
    retained_digest: Option<[u8; 32]>,
    signed_transaction_bytes: Option<&[u8]>,
) -> Option<[u8; 32]> {
    let retained_digest = retained_digest.filter(|digest| *digest != [0; 32])?;
    let signed_transaction_bytes = signed_transaction_bytes?;
    (*blake3_hash(signed_transaction_bytes).as_bytes() == retained_digest)
        .then_some(retained_digest)
}

fn decode_canonical_repair_report(bytes: &[u8]) -> Option<RepairReportV1> {
    if bytes.is_empty() {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let report: RepairReportV1 = norito::decode_from_bytes(bytes).ok()?;
    if report.validate().is_err() || norito::to_bytes(&report).ok()?.as_slice() != bytes {
        return None;
    }
    Some(report)
}

fn repair_operation_ticket_id(
    operation: &sorafs_node::repair_transaction_forwarder::RepairOperationV1,
) -> Option<String> {
    match operation {
        sorafs_node::repair_transaction_forwarder::RepairOperationV1::Submit(instruction) => {
            decode_canonical_repair_report(instruction.report_payload())
                .map(|report| report.ticket_id.0)
        }
        sorafs_node::repair_transaction_forwarder::RepairOperationV1::Action(instruction) => {
            Some(instruction.ticket_id().clone())
        }
        sorafs_node::repair_transaction_forwarder::RepairOperationV1::Appeal(instruction) => {
            Some(instruction.ticket_id().clone())
        }
    }
}

fn classify_repair_semantic_reconciliation(
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
    finalized: Option<&RepairFinalizedTaskV1>,
) -> Option<RepairSemanticReconciliationV1> {
    use sorafs_node::repair_transaction_forwarder::RepairOperationV1;

    match &request.operation {
        RepairOperationV1::Submit(instruction) => {
            let report = decode_canonical_repair_report(instruction.report_payload())?;
            let Some(finalized) = finalized else {
                return Some(RepairSemanticReconciliationV1::Ready(
                    RepairAuthorizationScopeV1::Provider(report.evidence.provider_id),
                ));
            };
            if finalized.task.source_identity == *instruction.source_identity()
                && finalized.task.canonical_report.as_slice()
                    == instruction.report_payload().as_slice()
                && finalized.task.submitted_by == request.authority
            {
                Some(RepairSemanticReconciliationV1::Finalized(
                    finalized.finalized_cursor,
                ))
            } else {
                Some(RepairSemanticReconciliationV1::Conflict(
                    finalized.finalized_cursor,
                ))
            }
        }
        RepairOperationV1::Action(instruction) => {
            let Some(finalized) = finalized else {
                return Some(RepairSemanticReconciliationV1::Deferred);
            };
            let idempotency_digest = sorafs_repair_idempotency_digest_v1(
                instruction.ticket_id(),
                instruction.action().idempotency_key(),
            );
            let action_digest =
                sorafs_repair_action_digest_v1(&request.authority, instruction).ok()?;
            if let Some(receipt) = finalized
                .task
                .action_receipts
                .iter()
                .find(|receipt| receipt.idempotency_digest == idempotency_digest)
            {
                return Some(if receipt.action_digest == action_digest {
                    RepairSemanticReconciliationV1::Finalized(finalized.finalized_cursor)
                } else {
                    RepairSemanticReconciliationV1::Conflict(finalized.finalized_cursor)
                });
            }
            if finalized.task.revision < *instruction.expected_revision() {
                return Some(RepairSemanticReconciliationV1::Deferred);
            }
            if finalized.task.revision > *instruction.expected_revision()
                || finalized.task.terminal_outcome.is_some()
            {
                return Some(RepairSemanticReconciliationV1::Conflict(
                    finalized.finalized_cursor,
                ));
            }
            Some(RepairSemanticReconciliationV1::Ready(
                RepairAuthorizationScopeV1::Provider(finalized.task.provider_id),
            ))
        }
        RepairOperationV1::Appeal(instruction) => {
            let Some(finalized) = finalized else {
                return Some(RepairSemanticReconciliationV1::Deferred);
            };
            let idempotency_digest = sorafs_repair_idempotency_digest_v1(
                instruction.ticket_id(),
                instruction.idempotency_key(),
            );
            let action_digest =
                sorafs_repair_action_digest_v1(&request.authority, instruction).ok()?;
            if let Some(receipt) = finalized
                .task
                .action_receipts
                .iter()
                .find(|receipt| receipt.idempotency_digest == idempotency_digest)
            {
                return Some(if receipt.action_digest == action_digest {
                    RepairSemanticReconciliationV1::Finalized(finalized.finalized_cursor)
                } else {
                    RepairSemanticReconciliationV1::Conflict(finalized.finalized_cursor)
                });
            }
            if finalized.task.revision < *instruction.expected_revision() {
                return Some(RepairSemanticReconciliationV1::Deferred);
            }
            let appeal_is_admissible = finalized.task.revision == *instruction.expected_revision()
                && finalized.task.appeal.is_none()
                && finalized.task.slash.is_some()
                && matches!(
                    finalized
                        .task
                        .terminal_outcome
                        .as_ref()
                        .map(|outcome| &outcome.kind),
                    Some(RepairLedgerTerminalKindV1::Escalated(_))
                );
            if !appeal_is_admissible {
                return Some(RepairSemanticReconciliationV1::Conflict(
                    finalized.finalized_cursor,
                ));
            }
            Some(RepairSemanticReconciliationV1::Ready(
                RepairAuthorizationScopeV1::ProviderOwner(finalized.task.provider_id),
            ))
        }
    }
}

fn reconcile_sorafs_repair_transaction_in_view(
    view: &impl StateReadOnly,
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
    finalized_cursor: RepairFinalizedCursorV1,
) -> Option<RepairTransactionReconciliationV1> {
    let ticket_id = repair_operation_ticket_id(&request.operation)?;
    let finalized = match FindSorafsRepairTask::new(ticket_id, Some(finalized_cursor)).execute(view)
    {
        Ok(finalized) => Some(finalized),
        Err(QueryExecutionFail::Find(FindError::SorafsRepairTask(_))) => None,
        Err(_) => return None,
    };
    let semantic = classify_repair_semantic_reconciliation(request, finalized.as_ref())?;
    Some(match semantic {
        RepairSemanticReconciliationV1::Finalized(cursor) => {
            RepairTransactionReconciliationV1::Finalized(cursor)
        }
        RepairSemanticReconciliationV1::Ready(scope) => RepairTransactionReconciliationV1::Ready {
            finalized_cursor,
            authority_is_authorized: scope.is_authorized(view.world(), &request.authority),
        },
        RepairSemanticReconciliationV1::Deferred => RepairTransactionReconciliationV1::Deferred,
        RepairSemanticReconciliationV1::Conflict(cursor) => {
            RepairTransactionReconciliationV1::Conflict(cursor)
        }
    })
}

fn reconcile_sorafs_repair_transaction(
    state: &SharedAppState,
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
) -> Option<RepairTransactionReconciliationV1> {
    let view = state.state.query_view();
    let finalized_cursor = sorafs_repair_finalized_cursor_from_view(&view)?;
    reconcile_sorafs_repair_transaction_in_view(&view, request, finalized_cursor)
}

fn inspect_indexed_repair_transaction(
    kura: &iroha_core::kura::Kura,
    transaction_hash: &HashOf<SignedTransaction>,
    block_height: NonZeroUsize,
    expected_block_hash: HashOf<BlockHeader>,
) -> RepairAuthoritativeTransactionOutcomeV1 {
    let Some(block) = kura.get_block(block_height) else {
        return classify_exact_repair_entrypoint_outcome(
            transaction_hash,
            false,
            std::iter::empty::<(HashOf<SignedTransaction>, RepairCommittedExternalOutcomeV1)>(),
        );
    };
    let Ok(block_height_u64) = u64::try_from(block_height.get()) else {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    };
    if block.header().height().get() != block_height_u64 || block.hash() != expected_block_hash {
        return RepairAuthoritativeTransactionOutcomeV1::Unavailable;
    }
    let external_entrypoint_count = block.external_entrypoint_count();
    classify_exact_repair_entrypoint_outcome(
        transaction_hash,
        true,
        block
            .entrypoint_results()
            .take(external_entrypoint_count)
            .filter_map(|(_, entrypoint, result)| {
                let TransactionEntrypoint::External(transaction) = entrypoint else {
                    return None;
                };
                let outcome = if result.0.is_ok() {
                    RepairCommittedExternalOutcomeV1::Applied
                } else {
                    RepairCommittedExternalOutcomeV1::Rejected
                };
                Some((transaction.hash(), outcome))
            }),
    )
}

fn observe_exact_sorafs_repair_transaction(
    state: &SharedAppState,
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
    transaction_hash: &HashOf<SignedTransaction>,
) -> Option<RepairExactTransactionObservationV1> {
    let view = state.state.view();
    let finalized_cursor = sorafs_repair_finalized_cursor_from_view(&view)?;
    let reconciliation =
        reconcile_sorafs_repair_transaction_in_view(&view, request, finalized_cursor)?;
    let transaction_outcome = match view.transactions().get(transaction_hash) {
        None => RepairAuthoritativeTransactionOutcomeV1::Absent,
        Some(block_height) if block_height.get() > view.block_hashes().len() => {
            RepairAuthoritativeTransactionOutcomeV1::Unavailable
        }
        Some(block_height) => {
            let Some(expected_block_hash) = view
                .block_hashes()
                .get(block_height.get().saturating_sub(1))
                .copied()
            else {
                return Some(RepairExactTransactionObservationV1 {
                    reconciliation,
                    finalized_cursor,
                    transaction_outcome: RepairAuthoritativeTransactionOutcomeV1::Unavailable,
                });
            };
            inspect_indexed_repair_transaction(
                view.kura(),
                transaction_hash,
                block_height,
                expected_block_hash,
            )
        }
    };
    Some(RepairExactTransactionObservationV1 {
        reconciliation,
        finalized_cursor,
        transaction_outcome,
    })
}

#[cfg(test)]
mod repair_transaction_forwarder_tests {
    use super::*;
    use iroha_data_model::{
        isi::sorafs::SorafsRepairClaimV1,
        sorafs::moderation_ledger::{
            REPAIR_LEDGER_TASK_VERSION_V1, RepairLedgerActionReceiptV1, RepairLedgerEscalatedV1,
            RepairLedgerLeaseV1, RepairLedgerSlashRecordV1, RepairLedgerTaskV1,
            RepairLedgerTerminalOutcomeV1,
        },
    };
    use sorafs_manifest::repair::{
        REPAIR_EVIDENCE_VERSION_V1, REPAIR_REPORT_VERSION_V1, RepairCauseV1, RepairEvidenceV1,
        RepairManualCauseV1, RepairTicketId,
    };
    use sorafs_node::repair_transaction_forwarder::{
        RepairOperationV1, RepairTransactionSigningRequestV1,
    };

    fn account(seed: u8) -> AccountId {
        AccountId::new(checked_test_keypair(seed).public_key().clone())
    }

    fn finalized_cursor() -> RepairFinalizedCursorV1 {
        RepairFinalizedCursorV1 {
            height: 11,
            block_hash: [0xB1; 32],
        }
    }

    fn finalized_task(
        submitted_by: AccountId,
        provider_id: [u8; 32],
        ticket_id: &str,
        revision: u64,
    ) -> RepairFinalizedTaskV1 {
        RepairFinalizedTaskV1 {
            finalized_cursor: finalized_cursor(),
            task: RepairLedgerTaskV1 {
                version: REPAIR_LEDGER_TASK_VERSION_V1,
                task_id: [0x41; 32],
                source_identity: [0x42; 32],
                ticket_id: ticket_id.to_owned(),
                canonical_report: vec![0x43],
                manifest_digest: [0x44; 32],
                provider_id,
                submitted_by,
                submitted_at_unix_ms: 1_000,
                revision,
                lease: None,
                terminal_outcome: None,
                slash: None,
                appeal: None,
                action_receipts: Vec::new(),
                updated_at_unix_ms: 1_000,
            },
        }
    }

    fn repair_report(authority: &AccountId, provider_id: [u8; 32]) -> RepairReportV1 {
        RepairReportV1 {
            version: REPAIR_REPORT_VERSION_V1,
            ticket_id: RepairTicketId("REP-TORII-FORWARDER".to_owned()),
            auditor_account: authority.to_string(),
            submitted_at_unix: 1,
            evidence: RepairEvidenceV1 {
                version: REPAIR_EVIDENCE_VERSION_V1,
                manifest_digest: [0x51; 32],
                provider_id,
                por_history_id: None,
                cause: RepairCauseV1::Manual(RepairManualCauseV1 {
                    reason: "test".to_owned(),
                }),
                evidence_json: None,
                notes: None,
            },
            notes: None,
        }
    }

    #[test]
    fn handoff_rebinds_report_to_runtime_authority_canonically() {
        let original = account(0x61);
        let runtime = account(0x62);
        let report = repair_report(&original, [0x63; 32]);
        let bytes = canonical_repair_report_for_authority(&runtime, &report)
            .expect("rebind and encode report");
        let rebound = decode_canonical_repair_report(&bytes).expect("decode rebound report");
        assert_eq!(rebound.auditor_account, runtime.to_string());
        assert_ne!(rebound.auditor_account, original.to_string());
    }

    #[test]
    fn submit_reconciliation_distinguishes_ready_finalized_and_conflict() {
        let authority = account(0x64);
        let provider_id = [0x65; 32];
        let report = repair_report(&authority, provider_id);
        let report_payload = norito::to_bytes(&report).expect("encode report");
        let instruction = SubmitSorafsRepairTask::new([0x66; 32], report_payload.clone());
        let request = RepairTransactionSigningRequestV1 {
            operation_id: [0x67; 32],
            chain_id: ChainId::from("repair-forwarder-test"),
            authority: authority.clone(),
            operation: RepairOperationV1::Submit(instruction),
        };
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, None),
            Some(RepairSemanticReconciliationV1::Ready(
                RepairAuthorizationScopeV1::Provider(provider_id)
            ))
        );

        let mut finalized = finalized_task(authority.clone(), provider_id, &report.ticket_id.0, 1);
        finalized.task.source_identity = [0x66; 32];
        finalized.task.canonical_report = report_payload;
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, Some(&finalized)),
            Some(RepairSemanticReconciliationV1::Finalized(finalized_cursor()))
        );
        finalized.task.source_identity = [0x68; 32];
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, Some(&finalized)),
            Some(RepairSemanticReconciliationV1::Conflict(finalized_cursor()))
        );
    }

    #[test]
    fn action_reconciliation_uses_consensus_receipt_digest() {
        let authority = account(0x69);
        let provider_id = [0x6A; 32];
        let instruction = ApplySorafsRepairTaskAction::new(
            "REP-ACTION".to_owned(),
            4,
            SorafsRepairTaskActionV1::Claim(SorafsRepairClaimV1 {
                lease_duration_ms: 60_000,
                idempotency_key: "claim-once".to_owned(),
            }),
        );
        let request = RepairTransactionSigningRequestV1 {
            operation_id: [0x6B; 32],
            chain_id: ChainId::from("repair-forwarder-test"),
            authority: authority.clone(),
            operation: RepairOperationV1::Action(instruction.clone()),
        };
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, None),
            Some(RepairSemanticReconciliationV1::Deferred)
        );
        let mut finalized = finalized_task(authority.clone(), provider_id, "REP-ACTION", 4);
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, Some(&finalized)),
            Some(RepairSemanticReconciliationV1::Ready(
                RepairAuthorizationScopeV1::Provider(provider_id)
            ))
        );

        let idempotency_digest = sorafs_repair_idempotency_digest_v1("REP-ACTION", "claim-once");
        let action_digest =
            sorafs_repair_action_digest_v1(&authority, &instruction).expect("digest action");
        finalized
            .task
            .action_receipts
            .push(RepairLedgerActionReceiptV1 {
                idempotency_digest,
                action_digest,
                resulting_revision: 5,
            });
        finalized.task.revision = 5;
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, Some(&finalized)),
            Some(RepairSemanticReconciliationV1::Finalized(finalized_cursor()))
        );
        finalized.task.action_receipts[0].action_digest = [0x6C; 32];
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, Some(&finalized)),
            Some(RepairSemanticReconciliationV1::Conflict(finalized_cursor()))
        );
    }

    #[test]
    fn appeal_reconciliation_requires_escalation_and_uses_receipts() {
        let authority = account(0x6D);
        let provider_id = [0x6E; 32];
        let instruction = SubmitSorafsRepairAppeal::new(
            "REP-APPEAL".to_owned(),
            7,
            [0x6F; 32],
            "appeal".to_owned(),
            "appeal-once".to_owned(),
        );
        let request = RepairTransactionSigningRequestV1 {
            operation_id: [0x70; 32],
            chain_id: ChainId::from("repair-forwarder-test"),
            authority: authority.clone(),
            operation: RepairOperationV1::Appeal(instruction.clone()),
        };
        let mut finalized = finalized_task(authority.clone(), provider_id, "REP-APPEAL", 7);
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, Some(&finalized)),
            Some(RepairSemanticReconciliationV1::Conflict(finalized_cursor()))
        );

        finalized.task.terminal_outcome = Some(RepairLedgerTerminalOutcomeV1 {
            kind: RepairLedgerTerminalKindV1::Escalated(RepairLedgerEscalatedV1 {
                slash_proposal_digest: [0x71; 32],
            }),
            lease_generation: 1,
            finalized_by: authority.clone(),
            finalized_at_unix_ms: 1_000,
        });
        finalized.task.slash = Some(RepairLedgerSlashRecordV1 {
            canonical_proposal: vec![0x72],
            proposal_digest: [0x71; 32],
            submitted_by: authority.clone(),
            submitted_at_unix_ms: 1_000,
        });
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, Some(&finalized)),
            Some(RepairSemanticReconciliationV1::Ready(
                RepairAuthorizationScopeV1::ProviderOwner(provider_id)
            ))
        );

        finalized
            .task
            .action_receipts
            .push(RepairLedgerActionReceiptV1 {
                idempotency_digest: sorafs_repair_idempotency_digest_v1(
                    "REP-APPEAL",
                    "appeal-once",
                ),
                action_digest: sorafs_repair_action_digest_v1(&authority, &instruction)
                    .expect("digest appeal"),
                resulting_revision: 8,
            });
        assert_eq!(
            classify_repair_semantic_reconciliation(&request, Some(&finalized)),
            Some(RepairSemanticReconciliationV1::Finalized(finalized_cursor()))
        );
    }

    #[test]
    fn local_queue_dispositions_preserve_strict_durability_boundaries() {
        assert_eq!(
            classify_local_repair_transaction_submission(&iroha_core::queue::Error::Full),
            RepairTransactionSubmissionDispositionV1::DefinitelyNotSubmitted
        );
        assert_eq!(
            classify_local_repair_transaction_submission(
                &iroha_core::queue::Error::PlanJournalDurabilityIndeterminate {
                    transaction_hash: iroha_crypto::HashOf::from_untyped_unchecked(
                        iroha_crypto::Hash::prehashed([0x73; 32]),
                    ),
                    reason: "unknown".to_owned(),
                }
            ),
            RepairTransactionSubmissionDispositionV1::Ambiguous
        );
        assert_eq!(
            classify_local_repair_transaction_submission(&iroha_core::queue::Error::IsInQueue),
            RepairTransactionSubmissionDispositionV1::Submitted
        );
        assert_eq!(
            classify_local_repair_transaction_submission(&iroha_core::queue::Error::Expired),
            RepairTransactionSubmissionDispositionV1::Rejected
        );
    }

    fn signed_transaction_hash(seed: u8) -> HashOf<SignedTransaction> {
        HashOf::from_untyped_unchecked(Hash::prehashed([seed; Hash::LENGTH]))
    }

    #[test]
    fn exact_entrypoint_classifier_requires_one_available_exact_result() {
        let expected = signed_transaction_hash(0x81);
        let other = signed_transaction_hash(0x82);
        assert_eq!(
            classify_exact_repair_entrypoint_outcome(
                &expected,
                false,
                Vec::<(HashOf<SignedTransaction>, RepairCommittedExternalOutcomeV1,)>::new(),
            ),
            RepairAuthoritativeTransactionOutcomeV1::Unavailable
        );
        assert_eq!(
            classify_exact_repair_entrypoint_outcome(
                &expected,
                true,
                [(other, RepairCommittedExternalOutcomeV1::Applied)],
            ),
            RepairAuthoritativeTransactionOutcomeV1::Unavailable
        );
        assert_eq!(
            classify_exact_repair_entrypoint_outcome(
                &expected,
                true,
                [(expected, RepairCommittedExternalOutcomeV1::Applied)],
            ),
            RepairAuthoritativeTransactionOutcomeV1::Applied
        );
        assert_eq!(
            classify_exact_repair_entrypoint_outcome(
                &expected,
                true,
                [(expected, RepairCommittedExternalOutcomeV1::Rejected)],
            ),
            RepairAuthoritativeTransactionOutcomeV1::Rejected
        );
        assert_eq!(
            classify_exact_repair_entrypoint_outcome(
                &expected,
                true,
                [
                    (expected, RepairCommittedExternalOutcomeV1::Applied),
                    (expected, RepairCommittedExternalOutcomeV1::Applied),
                ],
            ),
            RepairAuthoritativeTransactionOutcomeV1::Unavailable
        );
    }

    #[test]
    fn exact_delivery_uses_authoritative_presence_despite_cache_miss() {
        let cursor = finalized_cursor();
        assert_eq!(
            classify_exact_repair_delivery(
                RepairAuthoritativeTransactionOutcomeV1::Applied,
                cursor,
                cursor.height.saturating_sub(1),
                false,
            ),
            RepairExactDeliveryDispositionV1::Applied
        );
        assert_eq!(
            classify_exact_repair_delivery(
                RepairAuthoritativeTransactionOutcomeV1::Rejected,
                cursor,
                cursor.height.saturating_sub(1),
                false,
            ),
            RepairExactDeliveryDispositionV1::Rejected
        );
    }

    #[test]
    fn authoritative_absence_requires_cursor_advance_and_no_pending_signal() {
        let cursor = finalized_cursor();
        assert!(local_repair_evidence_blocks_absence_retry(true, None));
        assert!(local_repair_evidence_blocks_absence_retry(
            false,
            Some(crate::PipelineStatusKind::Queued),
        ));
        assert_eq!(
            classify_exact_repair_delivery(
                RepairAuthoritativeTransactionOutcomeV1::Absent,
                cursor,
                cursor.height.saturating_sub(1),
                false,
            ),
            RepairExactDeliveryDispositionV1::FinalizedAbsent
        );
        assert_eq!(
            classify_exact_repair_delivery(
                RepairAuthoritativeTransactionOutcomeV1::Absent,
                cursor,
                cursor.height,
                false,
            ),
            RepairExactDeliveryDispositionV1::Unavailable
        );
        assert_eq!(
            classify_exact_repair_delivery(
                RepairAuthoritativeTransactionOutcomeV1::Absent,
                cursor,
                cursor.height.saturating_sub(1),
                true,
            ),
            RepairExactDeliveryDispositionV1::Pending
        );
    }

    #[test]
    fn expired_cache_entry_is_neither_pending_nor_authoritative_rejection() {
        let cursor = finalized_cursor();
        let blocks_retry = local_repair_evidence_blocks_absence_retry(
            false,
            Some(crate::PipelineStatusKind::Expired),
        );
        assert!(!blocks_retry);
        assert_eq!(
            classify_exact_repair_delivery(
                RepairAuthoritativeTransactionOutcomeV1::Absent,
                cursor,
                cursor.height.saturating_sub(1),
                blocks_retry,
            ),
            RepairExactDeliveryDispositionV1::FinalizedAbsent
        );
    }

    #[test]
    fn unavailable_exact_block_or_entrypoint_always_defers() {
        let cursor = finalized_cursor();
        assert_eq!(
            classify_exact_repair_delivery(
                RepairAuthoritativeTransactionOutcomeV1::Unavailable,
                cursor,
                cursor.height.saturating_sub(1),
                false,
            ),
            RepairExactDeliveryDispositionV1::Unavailable
        );
    }

    #[test]
    fn exact_finalization_requires_the_retained_canonical_byte_digest() {
        let bytes = b"canonical signed transaction bytes";
        let digest = *blake3_hash(bytes).as_bytes();
        assert_eq!(
            retained_repair_transaction_digest_for_finalization(Some(digest), Some(bytes)),
            Some(digest)
        );
        assert_eq!(
            retained_repair_transaction_digest_for_finalization(None, Some(bytes)),
            None
        );
        assert_eq!(
            retained_repair_transaction_digest_for_finalization(Some([0; 32]), Some(bytes)),
            None
        );
        assert_eq!(
            retained_repair_transaction_digest_for_finalization(Some([0xA5; 32]), Some(bytes)),
            None
        );
        assert_eq!(
            retained_repair_transaction_digest_for_finalization(Some(digest), None),
            None
        );
    }

    #[test]
    fn disabled_native_repair_gate_suppresses_claim_renew_and_execute() {
        for disposition in [
            NativeRepairTaskDispositionV1::Claim,
            NativeRepairTaskDispositionV1::Renew {
                lease_generation: 7,
            },
            NativeRepairTaskDispositionV1::Execute,
        ] {
            assert_eq!(
                gate_native_repair_task_generation(false, disposition),
                NativeRepairTaskDispositionV1::Defer
            );
            assert_eq!(
                gate_native_repair_task_generation(true, disposition),
                disposition
            );
        }
    }

    #[test]
    fn native_repair_task_disposition_requires_the_exact_live_lease_owner() {
        let authority = account(0x74);
        let other = account(0x75);
        let mut finalized = finalized_task(authority.clone(), [0x76; 32], "REP-NATIVE", 2);
        assert_eq!(
            classify_native_repair_task(&finalized.task, &authority, 2_000, 500),
            NativeRepairTaskDispositionV1::Claim
        );

        finalized.task.lease = Some(RepairLedgerLeaseV1 {
            owner: other,
            generation: 1,
            acquired_at_unix_ms: 1_000,
            renewed_at_unix_ms: 1_000,
            expires_at_unix_ms: 10_000,
        });
        assert_eq!(
            classify_native_repair_task(&finalized.task, &authority, 2_000, 500),
            NativeRepairTaskDispositionV1::Defer
        );

        finalized.task.lease = Some(RepairLedgerLeaseV1 {
            owner: authority.clone(),
            generation: 2,
            acquired_at_unix_ms: 1_000,
            renewed_at_unix_ms: 1_500,
            expires_at_unix_ms: 2_400,
        });
        assert_eq!(
            classify_native_repair_task(&finalized.task, &authority, 2_000, 500),
            NativeRepairTaskDispositionV1::Renew {
                lease_generation: 2
            }
        );
        assert_eq!(
            classify_native_repair_task(&finalized.task, &authority, 2_500, 500),
            NativeRepairTaskDispositionV1::Claim
        );

        finalized.task.lease.as_mut().unwrap().expires_at_unix_ms = 10_000;
        assert_eq!(
            classify_native_repair_task(&finalized.task, &authority, 2_000, 500),
            NativeRepairTaskDispositionV1::Execute
        );
        finalized.task.terminal_outcome = Some(RepairLedgerTerminalOutcomeV1 {
            kind: RepairLedgerTerminalKindV1::Failed(
                iroha_data_model::sorafs::moderation_ledger::RepairLedgerFailedV1 {
                    failure_digest: [0x77; 32],
                },
            ),
            lease_generation: 2,
            finalized_by: authority.clone(),
            finalized_at_unix_ms: 2_100,
        });
        assert_eq!(
            classify_native_repair_task(&finalized.task, &authority, 2_200, 500),
            NativeRepairTaskDispositionV1::Defer
        );
    }
}

async fn enqueue_sorafs_finalized_native_repair_work(
    state: &SharedAppState,
    cursor: &mut SorafsRepairTransactionForwarderCursorV1,
    scan: &mut SorafsRepairTransactionForwarderScanV1,
) {
    use sorafs_node::repair_transaction_forwarder::{
        RepairOperationV1, RepairTransactionContextV1,
    };

    let repair_generation_enabled = state.sorafs_node.repair_config().enabled();
    if !repair_generation_enabled {
        return;
    }
    let Some(signer) = state.sorafs_repair_transaction_signer.as_ref() else {
        return;
    };
    let authority = signer.authority();
    let Some(local_provider_id) = state.sorafs_node.capacity_usage().provider_id else {
        return;
    };
    let lease_duration_ms = match state
        .sorafs_node
        .repair_config()
        .claim_ttl_secs()
        .checked_mul(1_000)
    {
        Some(duration)
            if (REPAIR_LEDGER_MIN_LEASE_MS_V1..=REPAIR_LEDGER_MAX_LEASE_MS_V1)
                .contains(&duration) =>
        {
            duration
        }
        _ => {
            warn!("native SoraFS repair lease duration is outside consensus bounds");
            return;
        }
    };
    let Some(renew_before_ms) = state
        .sorafs_node
        .repair_config()
        .heartbeat_interval_secs()
        .checked_mul(1_000)
    else {
        warn!("native SoraFS repair renewal interval overflowed");
        return;
    };

    let page = {
        let view = state.state.query_view();
        let Some(finalized_cursor) = u64::try_from(view.block_hashes.len())
            .ok()
            .zip(view.block_hashes.last())
            .map(|(height, hash)| RepairFinalizedCursorV1 {
                height,
                block_hash: *hash.as_ref(),
            })
            .filter(|cursor| cursor.height != 0 && cursor.block_hash != [0; 32])
        else {
            return;
        };
        if !RepairAuthorizationScopeV1::Provider(local_provider_id)
            .is_authorized(view.world(), &authority)
        {
            scan.unauthorized_signer = scan.unauthorized_signer.saturating_add(1);
            return;
        }
        match FindSorafsRepairTasks::new(
            Some(finalized_cursor),
            cursor.after_task_id,
            SORAFS_NATIVE_REPAIR_TASK_SCAN_LIMIT_V1,
        )
        .execute(&view)
        {
            Ok(page) if page.finalized_cursor == finalized_cursor => page,
            Ok(_) | Err(_) => {
                scan.deferred = scan.deferred.saturating_add(1);
                return;
            }
        }
    };
    cursor.after_task_id = if page.has_more {
        page.next_after_task_id
    } else {
        None
    };
    let transaction_context = RepairTransactionContextV1 {
        chain_id: (*state.chain_id).clone(),
        finalized_cursor: page.finalized_cursor,
    };
    let now_unix_ms = iroha_network_time_now_ms();

    for task in page.tasks {
        scan.task_scanned = scan.task_scanned.saturating_add(1);
        if task.provider_id != local_provider_id {
            continue;
        }
        match gate_native_repair_task_generation(
            repair_generation_enabled,
            classify_native_repair_task(&task, &authority, now_unix_ms, renew_before_ms),
        ) {
            NativeRepairTaskDispositionV1::Claim => {
                let operation = RepairOperationV1::Action(ApplySorafsRepairTaskAction::new(
                    task.ticket_id.clone(),
                    task.revision,
                    SorafsRepairTaskActionV1::Claim(SorafsRepairClaimV1 {
                        lease_duration_ms,
                        idempotency_key: format!(
                            "native-repair-claim-v1:{}:{}",
                            hex::encode(task.task_id),
                            task.revision
                        ),
                    }),
                ));
                match state.sorafs_node.enqueue_repair_transaction(
                    authority.clone(),
                    operation,
                    &transaction_context,
                ) {
                    Ok(_) => scan.lease_enqueued = scan.lease_enqueued.saturating_add(1),
                    Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                }
            }
            NativeRepairTaskDispositionV1::Renew { lease_generation } => {
                let operation = RepairOperationV1::Action(ApplySorafsRepairTaskAction::new(
                    task.ticket_id.clone(),
                    task.revision,
                    SorafsRepairTaskActionV1::Renew(SorafsRepairRenewV1 {
                        lease_generation,
                        lease_duration_ms,
                        idempotency_key: format!(
                            "native-repair-renew-v1:{}:{}:{}",
                            hex::encode(task.task_id),
                            task.revision,
                            lease_generation
                        ),
                    }),
                ));
                match state.sorafs_node.enqueue_repair_transaction(
                    authority.clone(),
                    operation,
                    &transaction_context,
                ) {
                    Ok(_) => scan.lease_enqueued = scan.lease_enqueued.saturating_add(1),
                    Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                }
            }
            NativeRepairTaskDispositionV1::Execute => {
                if current_sorafs_repair_finalized_cursor(state)
                    != Some(transaction_context.finalized_cursor)
                {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                }
                let finalized_task = RepairFinalizedTaskV1 {
                    finalized_cursor: transaction_context.finalized_cursor,
                    task,
                };
                let node = state.sorafs_node.clone();
                let authority = authority.clone();
                let transaction_context = transaction_context.clone();
                let execution = tokio::task::spawn_blocking(move || {
                    node.execute_finalized_native_repair(
                        &finalized_task,
                        &authority,
                        &transaction_context,
                        now_unix_ms,
                    )
                })
                .await;
                match execution {
                    Ok(Ok(_)) => {
                        scan.terminal_enqueued = scan.terminal_enqueued.saturating_add(1);
                    }
                    Ok(Err(_)) | Err(_) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                }
            }
            NativeRepairTaskDispositionV1::Defer => {
                scan.deferred = scan.deferred.saturating_add(1);
            }
        }
    }
}

fn resume_sorafs_protocol_repair_handoffs(
    state: &SharedAppState,
    scan: &mut SorafsRepairTransactionForwarderScanV1,
) {
    let repair_handoff = SoraFsRepairTransactionHandoff::new(state);
    match state.sorafs_node.resume_pdp_terminal_handoffs(
        &repair_handoff,
        SORAFS_REPAIR_TRANSACTION_FORWARDER_SCAN_LIMIT_V1,
    ) {
        Ok(resumed) => scan.pdp_handoffs_resumed = resumed,
        Err(error) => {
            scan.deferred = scan.deferred.saturating_add(1);
            warn!(
                ?error,
                "failed to resume durable PDP terminal handoffs through the native repair adapter"
            );
        }
    }
    match state
        .sorafs_node
        .resume_potr_terminal_handoffs(&repair_handoff)
    {
        Ok(resumed) => scan.potr_handoffs_resumed = resumed,
        Err(error) => {
            scan.deferred = scan.deferred.saturating_add(1);
            warn!(
                ?error,
                "failed to resume durable PoTR terminal handoffs through the native repair adapter"
            );
        }
    }
}

pub(crate) fn spawn_sorafs_repair_transaction_forwarder_worker(
    state: SharedAppState,
    shutdown_signal: ShutdownSignal,
) {
    if !state.sorafs_node.is_enabled() {
        debug!("SoraFS repair transaction forwarder disabled: SoraFS storage is disabled");
        return;
    }
    if state.sorafs_repair_transaction_signer.is_none() {
        warn!(
            "SoraFS repair transaction forwarder has no runtime signer; finalized reconciliation remains active"
        );
    }
    let worker_interval = state
        .sorafs_node
        .config()
        .runtime_retention()
        .proof_outcome_forwarder_interval();

    tokio::spawn(async move {
        let mut interval = tokio::time::interval(worker_interval);
        let mut cursor = SorafsRepairTransactionForwarderCursorV1::default();
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
        loop {
            tokio::select! {
                () = shutdown_signal.receive() => break,
                _ = interval.tick() => {
                    let scan =
                        run_sorafs_repair_transaction_forwarder_scan(&state, &mut cursor).await;
                    if scan.scanned != 0
                        || scan.pdp_handoffs_resumed != 0
                        || scan.potr_handoffs_resumed != 0
                    {
                        debug!(
                            pdp_handoffs_resumed = scan.pdp_handoffs_resumed,
                            potr_handoffs_resumed = scan.potr_handoffs_resumed,
                            scanned = scan.scanned,
                            finalized = scan.finalized,
                            signed = scan.signed,
                            submitted = scan.submitted,
                            deferred = scan.deferred,
                            unauthorized_signer = scan.unauthorized_signer,
                            conflicted = scan.conflicted,
                            rejected = scan.rejected,
                            "processed durable native SoraFS repair transactions"
                        );
                    }
                }
            }
        }
    });
}

#[allow(clippy::too_many_lines)]
pub(crate) async fn run_sorafs_repair_transaction_forwarder_scan(
    state: &SharedAppState,
    cursor: &mut SorafsRepairTransactionForwarderCursorV1,
) -> SorafsRepairTransactionForwarderScanV1 {
    use sorafs_node::repair_transaction_forwarder::RepairTransactionDeliveryStateV1;

    let mut scan = SorafsRepairTransactionForwarderScanV1::default();
    resume_sorafs_protocol_repair_handoffs(state, &mut scan);
    enqueue_sorafs_finalized_native_repair_work(state, cursor, &mut scan).await;
    let pending = match state.sorafs_node.pending_repair_transactions_after(
        cursor.after_sequence,
        SORAFS_REPAIR_TRANSACTION_FORWARDER_SCAN_LIMIT_V1,
    ) {
        Ok(pending) => pending,
        Err(_) => {
            warn!("failed to load durable native SoraFS repair transactions");
            return scan;
        }
    };
    for delivery in pending {
        cursor.after_sequence = Some(delivery.sequence);
        scan.scanned = scan.scanned.saturating_add(1);
        if delivery.chain_id != *state.chain_id {
            if let Some(finalized_cursor) = current_sorafs_repair_finalized_cursor(state) {
                match state
                    .sorafs_node
                    .mark_repair_transaction_finalized_conflict(
                        delivery.operation_id,
                        finalized_cursor,
                    ) {
                    Ok(()) => scan.conflicted = scan.conflicted.saturating_add(1),
                    Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                }
            } else {
                scan.deferred = scan.deferred.saturating_add(1);
            }
            warn!("native SoraFS repair transaction belongs to another chain");
            continue;
        }
        let request = match state
            .sorafs_node
            .repair_transaction_operation_for_reconciliation(delivery.operation_id)
        {
            Ok(request)
                if request.operation_id == delivery.operation_id
                    && request.chain_id == delivery.chain_id
                    && request.authority == delivery.authority =>
            {
                request
            }
            Ok(_) | Err(_) => {
                scan.deferred = scan.deferred.saturating_add(1);
                warn!("failed to read exact native SoraFS repair semantics");
                continue;
            }
        };
        let exact_transaction_hash = if matches!(
            delivery.state,
            RepairTransactionDeliveryStateV1::Ambiguous
                | RepairTransactionDeliveryStateV1::Submitted
        ) {
            let Some(transaction_bytes) = delivery.signed_transaction_bytes.as_deref() else {
                scan.deferred = scan.deferred.saturating_add(1);
                continue;
            };
            let Some(transaction) =
                decode_sorafs_repair_signed_transaction(transaction_bytes, &delivery.chain_id)
            else {
                scan.deferred = scan.deferred.saturating_add(1);
                warn!("durable native SoraFS repair transaction bytes failed validation");
                continue;
            };
            Some(transaction.hash())
        } else {
            None
        };
        let local_evidence_before_observation =
            exact_transaction_hash
                .as_ref()
                .is_some_and(|transaction_hash| {
                    let queue_pending = state
                        .queue
                        .contains_pending_hash(transaction_hash.clone(), &state.state);
                    let cache_kind = state
                        .pipeline_status_cache
                        .lookup(transaction_hash)
                        .map(|entry| entry.kind);
                    local_repair_evidence_blocks_absence_retry(queue_pending, cache_kind)
                });
        let (reconciliation, exact_observation) = if let Some(transaction_hash) =
            exact_transaction_hash.as_ref()
        {
            let Some(observation) =
                observe_exact_sorafs_repair_transaction(state, &request, transaction_hash)
            else {
                scan.deferred = scan.deferred.saturating_add(1);
                warn!("authoritative SoraFS repair transaction observation failed");
                continue;
            };
            (observation.reconciliation, Some(observation))
        } else {
            let Some(reconciliation) = reconcile_sorafs_repair_transaction(state, &request) else {
                scan.deferred = scan.deferred.saturating_add(1);
                warn!("authoritative SoraFS repair transaction reconciliation failed");
                continue;
            };
            (reconciliation, None)
        };
        let (finalized_cursor, authority_is_authorized) = match reconciliation {
            RepairTransactionReconciliationV1::Finalized(finalized_cursor) => {
                match state
                    .sorafs_node
                    .mark_repair_transaction_semantic_finalized(
                        delivery.operation_id,
                        finalized_cursor,
                    ) {
                    Ok(()) => scan.finalized = scan.finalized.saturating_add(1),
                    Err(_) => {
                        scan.deferred = scan.deferred.saturating_add(1);
                        warn!("failed to checkpoint a finalized native SoraFS repair operation");
                    }
                }
                continue;
            }
            RepairTransactionReconciliationV1::Conflict(finalized_cursor) => {
                match state
                    .sorafs_node
                    .mark_repair_transaction_finalized_conflict(
                        delivery.operation_id,
                        finalized_cursor,
                    ) {
                    Ok(()) => scan.conflicted = scan.conflicted.saturating_add(1),
                    Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                }
                continue;
            }
            RepairTransactionReconciliationV1::Deferred => {
                scan.deferred = scan.deferred.saturating_add(1);
                continue;
            }
            RepairTransactionReconciliationV1::Ready {
                finalized_cursor,
                authority_is_authorized,
            } => (finalized_cursor, authority_is_authorized),
        };
        if !authority_is_authorized {
            scan.deferred = scan.deferred.saturating_add(1);
            scan.unauthorized_signer = scan.unauthorized_signer.saturating_add(1);
            warn!(
                repair_kind = ?delivery.kind,
                "native SoraFS repair transaction authority is not authorized by finalized state"
            );
            continue;
        }

        match delivery.state {
            RepairTransactionDeliveryStateV1::Ready => {
                let Some(signer) = state.sorafs_repair_transaction_signer.clone() else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                if signer.authority() != delivery.authority {
                    scan.deferred = scan.deferred.saturating_add(1);
                    scan.unauthorized_signer = scan.unauthorized_signer.saturating_add(1);
                    warn!(
                        repair_kind = ?delivery.kind,
                        "native SoraFS repair runtime signer does not match the durable authority"
                    );
                    continue;
                }
                let claimed = match state
                    .sorafs_node
                    .claim_repair_transaction_for_signing(delivery.operation_id)
                {
                    Ok(claimed) if claimed == request => claimed,
                    Ok(_) | Err(_) => {
                        let _ = state
                            .sorafs_node
                            .release_repair_transaction_signing_claim(delivery.operation_id);
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                };
                let Some((transaction, transaction_bytes)) =
                    sign_sorafs_repair_transaction(state, signer, &claimed).await
                else {
                    let _ = state
                        .sorafs_node
                        .release_repair_transaction_signing_claim(delivery.operation_id);
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                match state
                    .sorafs_node
                    .store_signed_repair_transaction(delivery.operation_id, &transaction_bytes)
                {
                    Ok(transaction_digest)
                        if transaction_digest == *blake3_hash(&transaction_bytes).as_bytes() =>
                    {
                        scan.signed = scan.signed.saturating_add(1);
                    }
                    Ok(_) | Err(_) => {
                        let _ = state
                            .sorafs_node
                            .release_repair_transaction_signing_claim(delivery.operation_id);
                        scan.deferred = scan.deferred.saturating_add(1);
                        continue;
                    }
                }
                if submit_sorafs_repair_transaction(
                    state,
                    delivery.operation_id,
                    transaction_bytes,
                    transaction,
                )
                .await
                {
                    scan.submitted = scan.submitted.saturating_add(1);
                } else {
                    scan.deferred = scan.deferred.saturating_add(1);
                }
            }
            RepairTransactionDeliveryStateV1::Signed => {
                let Some(transaction_bytes) = delivery.signed_transaction_bytes else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                let Some(transaction) =
                    decode_sorafs_repair_signed_transaction(&transaction_bytes, &delivery.chain_id)
                else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    warn!("durable native SoraFS repair transaction bytes failed validation");
                    continue;
                };
                if submit_sorafs_repair_transaction(
                    state,
                    delivery.operation_id,
                    transaction_bytes,
                    transaction,
                )
                .await
                {
                    scan.submitted = scan.submitted.saturating_add(1);
                } else {
                    scan.deferred = scan.deferred.saturating_add(1);
                }
            }
            RepairTransactionDeliveryStateV1::Ambiguous
            | RepairTransactionDeliveryStateV1::Submitted => {
                let (Some(transaction_hash), Some(observation)) =
                    (exact_transaction_hash.as_ref(), exact_observation)
                else {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                };
                if observation.finalized_cursor != finalized_cursor {
                    scan.deferred = scan.deferred.saturating_add(1);
                    continue;
                }
                let queue_pending_after_observation = state
                    .queue
                    .contains_pending_hash(transaction_hash.clone(), &state.state);
                let cache_kind_after_observation = state
                    .pipeline_status_cache
                    .lookup(transaction_hash)
                    .map(|entry| entry.kind);
                let local_evidence_blocks_absence_retry = local_evidence_before_observation
                    || local_repair_evidence_blocks_absence_retry(
                        queue_pending_after_observation,
                        cache_kind_after_observation,
                    );
                match classify_exact_repair_delivery(
                    observation.transaction_outcome,
                    observation.finalized_cursor,
                    delivery.baseline_finalized_height,
                    local_evidence_blocks_absence_retry,
                ) {
                    RepairExactDeliveryDispositionV1::Applied => {
                        let Some(transaction_digest) =
                            retained_repair_transaction_digest_for_finalization(
                                delivery.transaction_digest,
                                delivery.signed_transaction_bytes.as_deref(),
                            )
                        else {
                            scan.deferred = scan.deferred.saturating_add(1);
                            continue;
                        };
                        match state.sorafs_node.mark_repair_transaction_finalized(
                            delivery.operation_id,
                            transaction_digest,
                            observation.finalized_cursor,
                        ) {
                            Ok(()) => scan.finalized = scan.finalized.saturating_add(1),
                            Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                        }
                    }
                    RepairExactDeliveryDispositionV1::Pending => {
                        if delivery.state == RepairTransactionDeliveryStateV1::Ambiguous {
                            let _ = state
                                .sorafs_node
                                .mark_repair_transaction_submitted(delivery.operation_id);
                        }
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    RepairExactDeliveryDispositionV1::Rejected => {
                        match state.sorafs_node.mark_repair_transaction_rejected(
                            delivery.operation_id,
                            observation.finalized_cursor,
                        ) {
                            Ok(()) => scan.rejected = scan.rejected.saturating_add(1),
                            Err(_) => scan.deferred = scan.deferred.saturating_add(1),
                        }
                    }
                    RepairExactDeliveryDispositionV1::FinalizedAbsent => {
                        if state
                            .sorafs_node
                            .mark_repair_transaction_finalized_absent(
                                delivery.operation_id,
                                observation.finalized_cursor,
                            )
                            .is_err()
                        {
                            warn!(
                                "failed to checkpoint authoritative absence for a native SoraFS repair transaction"
                            );
                        }
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                    RepairExactDeliveryDispositionV1::Unavailable => {
                        scan.deferred = scan.deferred.saturating_add(1);
                    }
                }
            }
            RepairTransactionDeliveryStateV1::Signing => {
                scan.deferred = scan.deferred.saturating_add(1);
            }
        }
    }
    scan
}

async fn sign_sorafs_repair_transaction(
    state: &SharedAppState,
    signer: Arc<dyn crate::SoraFsRepairTransactionSigner>,
    request: &sorafs_node::repair_transaction_forwarder::RepairTransactionSigningRequestV1,
) -> Option<(SignedTransaction, Vec<u8>)> {
    if signer.authority() != request.authority || request.chain_id != *state.chain_id {
        return None;
    }
    let mut builder = TransactionBuilder::new(
        request.chain_id.clone(),
        request.authority.clone(),
        iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
    )
    .with_instructions([InstructionBox::from(request.operation.clone())]);
    builder.set_ttl(Duration::from_secs(300));
    let mut payload = builder.into_payload().ok()?;
    payload.fee_payment = crate::quote_internal_fee_payment(state, &payload).ok()?;
    let expected_payload = payload.clone();
    let transaction = tokio::task::spawn_blocking(move || signer.sign(payload))
        .await
        .ok()?
        .ok()?;
    if transaction.payload() != &expected_payload {
        return None;
    }
    let bytes = norito::to_bytes(&transaction).ok()?;
    Some((transaction, bytes))
}

fn decode_sorafs_repair_signed_transaction(
    bytes: &[u8],
    expected_chain_id: &ChainId,
) -> Option<SignedTransaction> {
    let max_bytes =
        sorafs_node::repair_transaction_forwarder::REPAIR_TRANSACTION_MAX_CANONICAL_BYTES_V1;
    if bytes.is_empty() || bytes.len() > max_bytes {
        return None;
    }
    norito::core::from_bytes_view(bytes).ok()?;
    let total_elements = bytes.len().checked_mul(8)?;
    let total_allocated_bytes = bytes.len().checked_mul(20)?.checked_add(512 * 1024)?;
    let limits = norito::DecodeLimits::new(
        max_bytes,
        max_bytes,
        total_elements,
        total_allocated_bytes,
        128,
    );
    let transaction =
        norito::decode_from_bytes_with_limits::<SignedTransaction>(bytes, limits).ok()?;
    if norito::to_bytes(&transaction).ok()?.as_slice() != bytes
        || transaction.verify_signature().is_err()
        || transaction.chain() != expected_chain_id
    {
        return None;
    }
    Some(transaction)
}

async fn submit_sorafs_repair_transaction(
    state: &SharedAppState,
    operation_id: [u8; 32],
    transaction_bytes: Vec<u8>,
    transaction: SignedTransaction,
) -> bool {
    if transaction.chain() != state.chain_id.as_ref() {
        return false;
    }
    let accepted = match crate::routing::accept_transaction_for_ingress(
        state.chain_id.clone(),
        state.state.clone(),
        transaction.clone(),
        &state.telemetry,
    ) {
        Ok(accepted) => accepted,
        Err(_) => {
            let exact_transaction_bytes = state
                .sorafs_node
                .begin_repair_transaction_submission(operation_id);
            if exact_transaction_bytes
                .as_ref()
                .is_ok_and(|exact| exact == &transaction_bytes)
            {
                if let Some(finalized_cursor) = current_sorafs_repair_finalized_cursor(state) {
                    let _ = state
                        .sorafs_node
                        .mark_repair_transaction_rejected(operation_id, finalized_cursor);
                }
            } else if exact_transaction_bytes.is_ok() {
                let _ = state
                    .sorafs_node
                    .mark_repair_transaction_not_submitted(operation_id);
            }
            return false;
        }
    };
    let durable_retry_claim = match state
        .queue
        .durable_plan_admission_claim_with_state(&accepted, state.state.as_ref())
    {
        Ok(claim) => claim,
        Err(_) => return false,
    };
    let routing_plan = if let Some(claim) = durable_retry_claim.as_ref() {
        claim.routing_plan.clone()
    } else {
        match state
            .queue
            .route_plan_with_state(&accepted, state.state.as_ref())
        {
            Ok(plan) => plan,
            Err(_) => return false,
        }
    };
    let routing_decision = routing_plan.coordinator_route();
    let exact_transaction_bytes = match state
        .sorafs_node
        .begin_repair_transaction_submission(operation_id)
    {
        Ok(bytes) => bytes,
        Err(_) => return false,
    };
    if exact_transaction_bytes != transaction_bytes {
        let _ = state
            .sorafs_node
            .mark_repair_transaction_not_submitted(operation_id);
        return false;
    }

    let disposition = if crate::should_execute_route_locally(state.as_ref(), routing_decision) {
        match crate::routing::push_accepted_transaction_for_ingress_with_routing_plan_strict_durable(
            state.queue.clone(),
            state.state.clone(),
            accepted,
            routing_plan,
        ) {
            Ok(_) => RepairTransactionSubmissionDispositionV1::Submitted,
            Err(crate::Error::PushIntoQueue { source, .. }) => {
                classify_local_repair_transaction_submission(source.as_ref())
            }
            Err(_) => RepairTransactionSubmissionDispositionV1::Ambiguous,
        }
    } else {
        let response = crate::execute_torii_transaction_via_proxy(
            state,
            transaction.into(),
            routing_plan,
            durable_retry_claim,
            true,
            crate::utils::ResponseFormat::Norito,
        )
        .await;
        if response.status() == StatusCode::ACCEPTED {
            RepairTransactionSubmissionDispositionV1::Submitted
        } else {
            RepairTransactionSubmissionDispositionV1::Ambiguous
        }
    };
    match disposition {
        RepairTransactionSubmissionDispositionV1::Submitted => state
            .sorafs_node
            .mark_repair_transaction_submitted(operation_id)
            .is_ok(),
        RepairTransactionSubmissionDispositionV1::DefinitelyNotSubmitted => {
            let _ = state
                .sorafs_node
                .mark_repair_transaction_not_submitted(operation_id);
            false
        }
        RepairTransactionSubmissionDispositionV1::Rejected => {
            if let Some(finalized_cursor) = current_sorafs_repair_finalized_cursor(state) {
                let _ = state
                    .sorafs_node
                    .mark_repair_transaction_rejected(operation_id, finalized_cursor);
            }
            false
        }
        RepairTransactionSubmissionDispositionV1::Ambiguous => false,
    }
}

struct ModerationMaintenancePassV1 {
    outcomes: Vec<sorafs_node::moderation_orchestrator::ModerationSubmitOutcomeV1>,
    snapshot: sorafs_node::moderation_orchestrator::ModerationFinalizedLedgerSnapshotV1,
    durable_health: sorafs_node::moderation_orchestrator::ModerationOrchestratorDurableHealthV1,
}

fn run_sorafs_moderation_maintenance_pass(
    orchestrator: &sorafs_node::moderation_orchestrator::ModerationOrchestratorV1,
    maintenance_authority: AccountId,
    maintenance_batch_limit: usize,
) -> Result<ModerationMaintenancePassV1, ModerationOrchestratorError> {
    let outcomes = orchestrator.run_maintenance(maintenance_authority, maintenance_batch_limit)?;
    let snapshot = orchestrator
        .snapshot()
        .ok_or(ModerationOrchestratorError::FinalizedReaderUnavailable)?;
    let durable_health = orchestrator.durable_health()?;
    Ok(ModerationMaintenancePassV1 {
        outcomes,
        snapshot,
        durable_health,
    })
}

fn finish_sorafs_moderation_maintenance_pass(
    runtime: &super::moderation_runtime::ModerationOrchestratorRuntimeV1,
    result: Result<
        Result<ModerationMaintenancePassV1, ModerationOrchestratorError>,
        tokio::task::JoinError,
    >,
) {
    let pass = match result {
        Ok(Ok(pass)) => pass,
        Ok(Err(error)) => {
            runtime.finish_failure();
            let response = moderation_orchestrator_error_response(error);
            warn!(
                http_status = response.status().as_u16(),
                "SoraFS finalized-chain moderation orchestrator worker failed closed",
            );
            return;
        }
        Err(error) => {
            runtime.finish_failure();
            warn!(
                cancelled = error.is_cancelled(),
                panicked = error.is_panic(),
                "SoraFS finalized-chain moderation orchestrator blocking task failed",
            );
            return;
        }
    };
    if let Err(error) = runtime.finish_success(pass.snapshot, pass.durable_health) {
        warn!(
            error_class = ?error,
            "SoraFS finalized-chain moderation projection failed its readiness gate",
        );
        return;
    }
    debug!(
        finalized_action_count = pass
            .outcomes
            .iter()
            .filter(|outcome| outcome.status == ModerationOperationStatusV1::Finalized)
            .count(),
        pending_action_count = pass
            .outcomes
            .iter()
            .filter(|outcome| outcome.status == ModerationOperationStatusV1::Pending)
            .count(),
        rejected_action_count = pass
            .outcomes
            .iter()
            .filter(|outcome| outcome.status == ModerationOperationStatusV1::Rejected)
            .count(),
        pending_submission_count = pass.durable_health.pending_submissions,
        pending_handoff_count = pass.durable_health.pending_handoffs,
        pending_panel_notification_count = pass.durable_health.pending_panel_notifications,
        "reconciled finalized SoraFS moderation state and deadline maintenance",
    );
}

pub(crate) fn spawn_sorafs_moderation_orchestrator_worker(
    state: SharedAppState,
    shutdown_signal: ShutdownSignal,
) {
    let Some(runtime) = state.sorafs_moderation_orchestrator.clone() else {
        debug!("SoraFS finalized-chain moderation orchestrator worker disabled");
        return;
    };
    let Some(config) = state.sorafs_moderation_orchestrator_worker.clone() else {
        warn!(
            "SoraFS finalized-chain moderation orchestrator exists without its operational worker configuration"
        );
        return;
    };
    let maintenance_authority = config.maintenance_authority;
    let maintenance_batch_limit = config.maintenance_batch_limit;
    let worker_interval = config.worker_interval;
    let worker_deadline = super::moderation_runtime::moderation_worker_deadline(worker_interval);

    tokio::spawn(async move {
        let mut interval = tokio::time::interval(worker_interval);
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
        loop {
            tokio::select! {
                () = shutdown_signal.receive() => {
                    runtime.mark_worker_stopped();
                    break;
                },
                _ = interval.tick() => {
                    if !runtime.begin_maintenance() {
                        runtime.mark_deadline_exceeded();
                        warn!(
                            "SoraFS moderation maintenance remained in flight; overlapping pass rejected"
                        );
                        continue;
                    }
                    let orchestrator = runtime.orchestrator();
                    let authority = maintenance_authority.clone();
                    let mut blocking = tokio::task::spawn_blocking(move || {
                        run_sorafs_moderation_maintenance_pass(
                            orchestrator.as_ref(),
                            authority,
                            maintenance_batch_limit,
                        )
                    });
                    let result = tokio::select! {
                        () = shutdown_signal.receive() => {
                            runtime.mark_worker_stopped();
                            break;
                        }
                        result = tokio::time::timeout(worker_deadline, &mut blocking) => result,
                    };
                    match result {
                        Ok(result) => {
                            finish_sorafs_moderation_maintenance_pass(runtime.as_ref(), result);
                        }
                        Err(_) => {
                            runtime.mark_deadline_exceeded();
                            warn!(
                                deadline_ms = u64::try_from(worker_deadline.as_millis())
                                    .unwrap_or(u64::MAX),
                                "SoraFS moderation maintenance exceeded its deadline; pass remains exclusively fenced",
                            );
                            let result = tokio::select! {
                                () = shutdown_signal.receive() => {
                                    runtime.mark_worker_stopped();
                                    break;
                                }
                                result = &mut blocking => result,
                            };
                            finish_sorafs_moderation_maintenance_pass(
                                runtime.as_ref(),
                                result,
                            );
                        }
                    }
                }
            }
        }
    });
}

pub(crate) async fn handle_post_sorafs_appeal_finance_deposit_reconcile(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled(
            "sorafs appeal finance deposit settlement reconciliation API is not enabled on this node",
        );
    }
    let verified =
        match require_appeal_finance_request_auth(&state, &headers, &method, &uri, body.as_ref()) {
            Ok(verified) => verified,
            Err(response) => return response,
        };
    let req = match json::from_slice::<AppealFinanceDepositSettleRequestDto>(body.as_ref()) {
        Ok(req) => req,
        Err(err) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!(
                    "failed to decode SoraFS appeal finance deposit settlement reconciliation JSON: {err}"
                ),
            );
        }
    };
    let (expected, record, _) = match load_appeal_finance_deposit_record_for_reconciliation(
        &state,
        &req.deposit_confirmation,
        &verified.account,
    ) {
        Ok(value) => value,
        Err(response) => return response,
    };
    let policy = &state.sorafs_appeal_finance_policy;
    let config = policy.settlement();
    let deposit_xor =
        match parse_appeal_quantity_literal("deposit_xor", &expected.deposit_xor.to_string()) {
            Ok(value) => value,
            Err(err) => return json_error(StatusCode::BAD_REQUEST, err.to_string()),
        };
    let verdict = match appeal_verdict_from_request(&req.outcome) {
        Ok(value) => value,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err),
    };
    let panel_size = req
        .panel_size
        .unwrap_or_else(|| config.default_panel_size());
    let breakdown = match config.settle(deposit_xor, panel_size, verdict) {
        Ok(value) => value,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err.to_string()),
    };
    let reconciliation = match appeal_finance_deposit_settlement_reconciliation(
        &expected, &record, policy, verdict, panel_size, &breakdown,
    ) {
        Ok(value) => value,
        Err(err) => return json_error(StatusCode::BAD_REQUEST, err),
    };
    (
        StatusCode::OK,
        JsonBody(appeal_finance_deposit_settlement_reconciliation_json(
            policy,
            &expected,
            &record,
            verdict,
            panel_size,
            &breakdown,
            &reconciliation,
        )),
    )
        .into_response()
}

pub(crate) async fn handle_post_sorafs_appeal_finance_deposit(
    State(state): State<SharedAppState>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    if !state.sorafs_node.is_enabled() {
        return feature_disabled("sorafs appeal finance deposit API is not enabled on this node");
    }
    let verified =
        match require_appeal_finance_request_auth(&state, &headers, &method, &uri, body.as_ref()) {
            Ok(verified) => verified,
            Err(response) => return response,
        };
    let req = match json::from_slice::<AppealFinanceDepositRequestDto>(body.as_ref()) {
        Ok(req) => req,
        Err(err) => {
            return json_error(
                StatusCode::BAD_REQUEST,
                format!("failed to decode SoraFS appeal finance deposit JSON: {err}"),
            );
        }
    };
    let policy = &state.sorafs_appeal_finance_policy;
    if let Err(response) = require_appeal_finance_asset_ready(&state, policy) {
        return response;
    }
    let deposit = match appeal_finance_deposit_instruction(req, &verified.account, policy) {
        Ok(deposit) => deposit,
        Err(DepositInstructionError::Forbidden(reason)) => {
            return json_error(StatusCode::FORBIDDEN, reason);
        }
        Err(DepositInstructionError::Invalid(reason)) => {
            return json_error(StatusCode::BAD_REQUEST, reason);
        }
    };
    let Some(submitter) = state.sorafs_appeal_settlement_submitter.as_ref() else {
        return json_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "SoraFS appeal finance durable transaction forwarder is not configured",
        );
    };
    let (finalized_cursor, record) = {
        let view = state.state.query_view();
        let Some(finalized_cursor) = appeal_finance_finalized_cursor_from_view(&view) else {
            return json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                "SoraFS appeal finance requires a non-empty finalized ledger",
            );
        };
        (
            finalized_cursor,
            view.world()
                .asset_escrows()
                .get(&deposit.expected.escrow_id)
                .cloned(),
        )
    };
    let operation =
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationV1::Open(
            appeal_finance_open_asset_lock(&deposit.expected),
        );
    let reconciliation_context = match norito::to_bytes(&AppealFinanceDepositOutboxContextV1 {
        version: APPEAL_FINANCE_DEPOSIT_OUTBOX_CONTEXT_VERSION_V1,
        policy_digest: policy.policy_digest,
        expected: deposit.expected.clone(),
    }) {
        Ok(bytes) => bytes,
        Err(error) => {
            return json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("failed to encode SoraFS appeal finance deposit context: {error}"),
            );
        }
    };
    let signing_request =
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionSigningRequestV1 {
            operation_id: [0; 32],
            chain_id: (*state.chain_id).clone(),
            authority: deposit.expected.payer_account.clone(),
            operation: operation.clone(),
            expected_record: None,
            reconciliation_context: reconciliation_context.clone(),
            baseline_finalized_cursor: finalized_cursor,
        };
    match sorafs_node::appeal_finance_transaction_forwarder::reconcile_appeal_finance_operation_v1(
        &signing_request,
        finalized_cursor,
        record.as_ref(),
    ) {
        Ok(
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationReconciliationV1::Finalized,
        ) => {
            return (
                StatusCode::OK,
                JsonBody(appeal_finance_deposit_submission_json(
                    policy,
                    &deposit,
                    "already_finalized",
                    None,
                    submitter.signer_count(finalized_cursor.height),
                )),
            )
                .into_response();
        }
        Ok(
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationReconciliationV1::Conflict,
        ) => {
            return (
                StatusCode::CONFLICT,
                JsonBody(appeal_finance_deposit_submission_json(
                    policy,
                    &deposit,
                    "finalized_identity_conflict",
                    None,
                    submitter.signer_count(finalized_cursor.height),
                )),
            )
                .into_response();
        }
        Ok(
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceOperationReconciliationV1::Ready,
        ) => {}
        Err(error) => {
            return json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                format!("failed to reconcile SoraFS appeal finance deposit: {error}"),
            );
        }
    }
    if submitter
        .signer_for(&deposit.expected.payer_account, finalized_cursor.height)
        .is_err()
    {
        return (
            StatusCode::SERVICE_UNAVAILABLE,
            JsonBody(appeal_finance_deposit_submission_json(
                policy,
                &deposit,
                "missing_required_runtime_signer",
                None,
                submitter.signer_count(finalized_cursor.height),
            )),
        )
            .into_response();
    }
    let context =
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionContextV1 {
            chain_id: (*state.chain_id).clone(),
            finalized_cursor,
            expected_record: None,
            reconciliation_context,
        };
    let enqueue = match submitter.forwarder.enqueue_unsigned_operation(
        deposit.expected.payer_account.clone(),
        operation,
        &context,
    ) {
        Ok(enqueue) => enqueue,
        Err(
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarderError::IdentityConflict
            | sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarderError::DeadLetterConflict,
        ) => {
            return (
                StatusCode::CONFLICT,
                JsonBody(appeal_finance_deposit_submission_json(
                    policy,
                    &deposit,
                    "durable_identity_conflict",
                    None,
                    submitter.signer_count(finalized_cursor.height),
                )),
            )
                .into_response();
        }
        Err(error) => {
            return json_error(
                StatusCode::SERVICE_UNAVAILABLE,
                format!("failed to durably enqueue SoraFS appeal finance deposit: {error}"),
            );
        }
    };
    let status = match enqueue {
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionEnqueueResultV1::Inserted { .. } => {
            "durably_enqueued"
        }
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionEnqueueResultV1::Existing { .. } => {
            "already_durably_enqueued"
        }
    };
    let operation_id_hex = hex::encode(enqueue.operation_id());
    (
        StatusCode::ACCEPTED,
        JsonBody(appeal_finance_deposit_submission_json(
            policy,
            &deposit,
            status,
            Some(&operation_id_hex),
            submitter.signer_count(finalized_cursor.height),
        )),
    )
        .into_response()
}

