    #[tokio::test]
    async fn reputation_read_routes_return_retained_projection_and_proof() {
        let (mut app, _dir) = sorafs_app_state_with_reputation_storage();
        let envelope = reputation_snapshot_fixture();
        let snapshot = envelope.snapshot.clone();
        let expected_proof = snapshot
            .merkle_proof("provider-a")
            .expect("provider proof fixture");

        attach_reputation_committed_projection(
            &mut app,
            committed_reputation_projection_fixture(envelope),
        );
        // The process-local node read model is deliberately empty: every
        // response below must come from the committed runtime boundary.
        assert!(
            app.sorafs_node
                .latest_signed_reputation_snapshot()
                .is_none()
        );

        let response = handle_get_sorafs_reputation_latest(
            State(app.clone()),
            HeaderMap::new(),
            axum::extract::RawQuery(None),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let latest_etag = response.headers().get(ETAG).cloned().expect("latest etag");
        assert_eq!(
            response
                .headers()
                .get(CACHE_CONTROL)
                .and_then(|value| value.to_str().ok()),
            Some(REPUTATION_CACHE_CONTROL)
        );
        let body_bytes = body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("collect latest body");
        let value: Value = norito::json::from_slice(&body_bytes).expect("decode latest JSON");
        assert_eq!(
            value.get("merkle_root_hex").and_then(Value::as_str),
            Some(hex::encode(snapshot.merkle_root).as_str())
        );
        let providers = value
            .get("providers")
            .and_then(Value::as_array)
            .expect("providers array");
        assert_eq!(providers.len(), 2);
        assert_eq!(value.get("provider_count").and_then(Value::as_u64), Some(2));
        assert_eq!(
            value.get("returned_provider_count").and_then(Value::as_u64),
            Some(2)
        );
        assert_eq!(
            value.get("limit").and_then(Value::as_u64),
            Some(DEFAULT_LIST_LIMIT as u64)
        );
        assert_eq!(
            value.get("truncated_providers").and_then(Value::as_bool),
            Some(false)
        );

        let response = handle_get_sorafs_reputation_latest(
            State(app.clone()),
            HeaderMap::new(),
            axum::extract::RawQuery(Some("limit=1".to_owned())),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let capped_etag = response.headers().get(ETAG).cloned().expect("capped etag");
        assert_ne!(latest_etag, capped_etag);
        let body_bytes = body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("collect capped latest body");
        let value: Value =
            norito::json::from_slice(&body_bytes).expect("decode capped latest JSON");
        assert_eq!(value.get("provider_count").and_then(Value::as_u64), Some(2));
        assert_eq!(
            value.get("returned_provider_count").and_then(Value::as_u64),
            Some(1)
        );
        assert_eq!(value.get("limit").and_then(Value::as_u64), Some(1));
        assert_eq!(
            value.get("truncated_providers").and_then(Value::as_bool),
            Some(true)
        );
        let providers = value
            .get("providers")
            .and_then(Value::as_array)
            .expect("capped providers array");
        assert_eq!(providers.len(), 1);

        let mut conditional_headers = HeaderMap::new();
        conditional_headers.insert(IF_NONE_MATCH, latest_etag.clone());
        let response = handle_get_sorafs_reputation_latest(
            State(app.clone()),
            conditional_headers,
            axum::extract::RawQuery(None),
        )
        .await;
        assert_eq!(response.status(), StatusCode::NOT_MODIFIED);
        assert_eq!(response.headers().get(ETAG), Some(&latest_etag));

        let response = handle_get_sorafs_reputation_provider(
            State(app.clone()),
            HeaderMap::new(),
            Path("provider-a".to_owned()),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let body_bytes = body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("collect provider body");
        let value: Value = norito::json::from_slice(&body_bytes).expect("decode provider JSON");
        let provider = value
            .get("provider")
            .and_then(Value::as_object)
            .expect("provider object");
        assert_eq!(
            provider.get("provider_id").and_then(Value::as_str),
            Some("provider-a")
        );
        let proof = value
            .get("proof")
            .and_then(Value::as_object)
            .expect("proof object");
        assert_eq!(
            proof.get("provider_id").and_then(Value::as_str),
            Some("provider-a")
        );
        assert_eq!(
            proof.get("leaf_index").and_then(Value::as_u64),
            Some(u64::from(expected_proof.leaf_index))
        );
        let siblings = proof
            .get("siblings_hex")
            .and_then(Value::as_array)
            .expect("siblings array");
        assert_eq!(siblings.len(), expected_proof.siblings.len());

        let response = handle_get_sorafs_reputation_snapshot(
            State(app.clone()),
            HeaderMap::new(),
            Path(hex::encode(snapshot.snapshot_id)),
            axum::extract::RawQuery(None),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let body_bytes = body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("collect historical body");
        let value: Value = norito::json::from_slice(&body_bytes).expect("decode historical JSON");
        assert_eq!(
            value.get("snapshot_id_hex").and_then(Value::as_str),
            Some(hex::encode(snapshot.snapshot_id).as_str())
        );

        let response =
            handle_get_sorafs_reputation_weights(State(app.clone()), HeaderMap::new()).await;
        assert_eq!(response.status(), StatusCode::OK);
        let body_bytes = body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("collect weights body");
        let value: Value = norito::json::from_slice(&body_bytes).expect("decode weights JSON");
        assert_eq!(
            value.get("alpha_bps").and_then(Value::as_u64),
            Some(u64::from(snapshot.alpha_bps))
        );
        assert!(value.get("weights").and_then(Value::as_object).is_some());

        let response = handle_get_sorafs_reputation_events(
            State(app.clone()),
            HeaderMap::new(),
            axum::extract::RawQuery(Some("since=0&limit=1".to_owned())),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let events_etag = response.headers().get(ETAG).cloned().expect("events etag");
        let body_bytes = body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("collect events body");
        let value: Value = norito::json::from_slice(&body_bytes).expect("decode events JSON");
        assert_eq!(value.get("count").and_then(Value::as_u64), Some(1));
        assert_eq!(value.get("next_since").and_then(Value::as_u64), Some(1));
        let events = value
            .get("events")
            .and_then(Value::as_array)
            .expect("events array");
        let event = events
            .first()
            .and_then(Value::as_object)
            .expect("event object");
        assert_eq!(event.get("sequence").and_then(Value::as_u64), Some(1));
        assert_eq!(
            event.get("snapshot_id_hex").and_then(Value::as_str),
            Some(hex::encode(snapshot.snapshot_id).as_str())
        );

        let response = handle_get_sorafs_reputation_events_stream(
            State(app.clone()),
            axum::extract::RawQuery(Some("since=0&limit=1".to_owned())),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        assert!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok())
                .is_some_and(|value| value.contains("text/event-stream"))
        );
        let mut body = response.into_body();
        let frame = tokio::time::timeout(std::time::Duration::from_secs(1), body.frame())
            .await
            .expect("SSE frame timeout")
            .expect("SSE body frame")
            .expect("SSE data frame");
        let data = frame.into_data().expect("SSE data frame");
        let text = String::from_utf8(data.to_vec()).expect("SSE frame UTF-8");
        assert!(text.contains("event: reputation_snapshot"));
        assert!(text.contains("id: 1"));
        assert!(text.contains(hex::encode(snapshot.snapshot_id).as_str()));

        let mut conditional_headers = HeaderMap::new();
        conditional_headers.insert(IF_NONE_MATCH, events_etag.clone());
        let response = handle_get_sorafs_reputation_events(
            State(app),
            conditional_headers,
            axum::extract::RawQuery(Some("since=0&limit=1".to_owned())),
        )
        .await;
        assert_eq!(response.status(), StatusCode::NOT_MODIFIED);
        assert_eq!(response.headers().get(ETAG), Some(&events_etag));
    }

    #[tokio::test]
    async fn reputation_snapshot_route_returns_exact_retained_history_and_rejects_evicted_ids() {
        let generated_at_unix = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock after epoch")
            .as_secs();
        let older = reputation_snapshot_fixture_with_identity([0xA9; 16], None, generated_at_unix);
        let newer = reputation_snapshot_fixture_with_identity(
            [0xAA; 16],
            Some(older.snapshot.snapshot_id),
            generated_at_unix + 1,
        );
        let projection = committed_reputation_projection_fixture(newer.clone());
        let (mut app, _dir) = sorafs_app_state_with_reputation_storage();
        attach_reputation_committed_history(
            &mut app,
            projection.clone(),
            vec![older.snapshot.clone(), newer.snapshot.clone()],
        );

        let response = handle_get_sorafs_reputation_snapshot(
            State(app.clone()),
            HeaderMap::new(),
            Path(hex::encode(older.snapshot.snapshot_id)),
            axum::extract::RawQuery(None),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let body_bytes = body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("collect retained historical body");
        let value: Value =
            norito::json::from_slice(&body_bytes).expect("decode retained historical JSON");
        assert_eq!(
            value.get("snapshot_id_hex").and_then(Value::as_str),
            Some(hex::encode(older.snapshot.snapshot_id).as_str())
        );
        assert_ne!(
            value.get("snapshot_id_hex").and_then(Value::as_str),
            Some(hex::encode(newer.snapshot.snapshot_id).as_str()),
            "the snapshot-id route must not substitute the latest snapshot"
        );

        let (mut evicted_app, _evicted_dir) = sorafs_app_state_with_reputation_storage();
        attach_reputation_committed_history(
            &mut evicted_app,
            projection,
            vec![newer.snapshot.clone()],
        );
        let response = handle_get_sorafs_reputation_snapshot(
            State(evicted_app),
            HeaderMap::new(),
            Path(hex::encode(older.snapshot.snapshot_id)),
            axum::extract::RawQuery(None),
        )
        .await;
        assert_eq!(response.status(), StatusCode::NOT_FOUND);
    }

