    fn deadline_expired_pdp_archive_fixture(challenge: &PdpChallengeV1) -> PdpGovernanceArchiveV1 {
        let canonical_challenge =
            norito::to_bytes(challenge).expect("encode canonical PDP challenge");
        let sampled_hot_leaves = challenge
            .samples
            .iter()
            .map(|sample| sample.hot_leaf_indices.len())
            .sum::<usize>();
        let archive = PdpGovernanceArchiveV1 {
            version: PDP_GOVERNANCE_ARCHIVE_VERSION_V1,
            sequence: 1,
            challenge_id: challenge.challenge_id,
            commitment_digest: challenge.commitment_digest,
            manifest_digest: challenge.manifest_digest,
            provider_id: challenge.provider_id,
            epoch_id: challenge.epoch_id,
            decision: PdpTerminalDecisionV1::Rejected(PdpRejectionReasonV1::DeadlineExpired),
            proof_digest: None,
            sampled_segments: u16::try_from(challenge.samples.len())
                .expect("fixture segment count fits u16"),
            sampled_hot_leaves: u16::try_from(sampled_hot_leaves)
                .expect("fixture hot-leaf count fits u16"),
            sampled_bytes: 0,
            issued_at_unix: challenge.issued_at_unix,
            response_deadline_unix: challenge.response_deadline_unix,
            decided_at_unix: challenge.response_deadline_unix,
            admission_envelope_digest: PROOF_OUTCOME_TEST_ADMISSION_DIGEST,
            canonical_challenge,
            canonical_proof: None,
        };
        archive
            .validate()
            .expect("deadline-expired PDP archive fixture validates");
        archive
    }

    fn app_with_finalized_proof_outcomes() -> (
        SharedAppState,
        PdpChallengeV1,
        PotrReceiptV1,
        ProofOutcomeFinalizedCursorV1,
    ) {
        let receipt = canonical_potr_receipt_fixture();
        let challenge: PdpChallengeV1 = norito::decode_from_bytes(include_bytes!(
            "../../../../fixtures/sorafs_manifest/pdp/challenge_v1.to"
        ))
        .expect("decode canonical PDP challenge fixture");
        challenge
            .validate()
            .expect("canonical PDP challenge fixture validates");
        assert_eq!(challenge.provider_id, receipt.provider_id);
        assert_eq!(challenge.manifest_digest, receipt.manifest_digest);

        let manager_key = KeyPair::try_from_seed(vec![0x91; 32], Algorithm::Ed25519)
            .expect("derive proof-outcome manager key");
        let manager_id = AccountId::new(manager_key.public_key().clone());
        let manager_account = Account::new(manager_id.clone()).build(&manager_id);
        let mut world = World::with([], [manager_account], []);
        let provider_id = ProviderId::new(receipt.provider_id);
        let mut manager_permissions = Permissions::new();
        manager_permissions.insert(Permission::from(CanManageSorafsProofOutcomePolicy));
        manager_permissions.insert(Permission::from(CanRecordSorafsProofOutcome {
            provider_id,
        }));
        world
            .account_permissions_mut_for_testing()
            .insert(manager_id.clone(), manager_permissions);
        world
            .provider_owners_mut_for_testing()
            .insert(provider_id, manager_id.clone());

        let gateway_public_key: [u8; 32] = receipt
            .gateway_signature
            .as_ref()
            .expect("fixture gateway signature")
            .public_key
            .as_slice()
            .try_into()
            .expect("fixture gateway Ed25519 public key");
        let provider_public_key = receipt
            .provider_signature
            .as_ref()
            .expect("fixture provider signature")
            .public_key
            .clone();
        let (pdp_algorithm, pdp_public_key) = manager_key
            .public_key()
            .try_to_bytes()
            .expect("encode fixture PDP public key");
        assert_eq!(pdp_algorithm, Algorithm::Ed25519);
        let policy = ProofOutcomeSignerPolicyV1 {
            version: PROOF_OUTCOME_SIGNER_POLICY_VERSION_V1,
            provider_id,
            revision: 1,
            predecessor_digest: None,
            admission_envelope_digest: PROOF_OUTCOME_TEST_ADMISSION_DIGEST,
            pdp_public_key: pdp_public_key
                .try_into()
                .expect("fixture PDP Ed25519 public key"),
            potr_mldsa_public_key: provider_public_key,
            gateway_public_key,
            valid_from_unix: 1_699_999_900,
            valid_until_unix: PROOF_OUTCOME_TEST_BLOCK_TIME_UNIX + 100,
        };
        let pdp_archive = deadline_expired_pdp_archive_fixture(&challenge);
        let pdp_submission = SubmitSorafsProofOutcome::new(SorafsProofOutcomeSubmissionV1::Pdp(
            SorafsPdpProofOutcomeSubmissionV1 {
                archive_payload: norito::to_bytes(&pdp_archive)
                    .expect("encode canonical PDP archive"),
            },
        ));
        let potr_submission = SubmitSorafsProofOutcome::new(SorafsProofOutcomeSubmissionV1::Potr(
            SorafsPotrProofOutcomeSubmissionV1 {
                receipt_payload: receipt
                    .signed_receipt_bytes()
                    .expect("encode canonical signed PoTR receipt"),
                admission_envelope_digest: PROOF_OUTCOME_TEST_ADMISSION_DIGEST,
            },
        ));

        let mut app = mk_app_state_for_tests_with_world(world);
        let header = BlockHeader::new(
            NonZeroU64::new(1).expect("non-zero fixture block height"),
            None,
            None,
            None,
            PROOF_OUTCOME_TEST_BLOCK_TIME_UNIX * 1_000,
            0,
        );
        let finalized_cursor = ProofOutcomeFinalizedCursorV1 {
            height: 1,
            block_hash: *HashOf::new(&header).as_ref(),
        };
        let app_inner = Arc::get_mut(&mut app).expect("unique proof-outcome app state");
        let core_state =
            Arc::get_mut(&mut app_inner.state).expect("unique proof-outcome core state");
        {
            let mut block = core_state.block(header.clone());
            let mut transaction = block.transaction();
            SetSorafsProofOutcomeSignerPolicy::new(policy)
                .execute(&manager_id, &mut transaction)
                .expect("activate fixture proof-outcome signer policy");
            pdp_submission
                .execute(&manager_id, &mut transaction)
                .expect("commit fixture PDP outcome");
            potr_submission
                .execute(&manager_id, &mut transaction)
                .expect("commit fixture PoTR outcome");
            transaction.apply();
            block.commit().expect("commit fixture proof-outcome block");
        }
        core_state.push_block_hash_for_testing(HashOf::new(&header));
        (app, challenge, receipt, finalized_cursor)
    }

    async fn proof_stream_body(response: Response) -> (StatusCode, String) {
        let status = response.status();
        let body = BodyExt::collect(response.into_body())
            .await
            .expect("collect proof-stream response")
            .to_bytes();
        (
            status,
            String::from_utf8(body.to_vec()).expect("proof-stream response is UTF-8"),
        )
    }

    fn app_with_local_por_manifest(
        status: Option<PinStatus>,
        mutate_record: impl FnOnce(&mut PinManifestRecord),
    ) -> (
        SharedAppState,
        ManifestV1,
        [u8; 32],
        PinManifestFinalizedCursorV1,
        TempDir,
    ) {
        let provider_id = [0xC4; 32];
        let payload = vec![0xA7; 192 * 1024];
        let plan = CarBuildPlan::single_file(&payload).expect("canonical PoR fixture plan");
        let manifest = manifest_for_payload(0xC1, &payload);
        let (node, storage_dir) = sorafs_node_with_temp_storage();
        let mut reader = payload.as_slice();
        node.ingest_manifest(&manifest, &plan, &mut reader)
            .expect("ingest canonical PoR fixture");
        seed_capacity_declaration(
            &node,
            provider_id,
            format!(
                "{}.{}@{}",
                manifest.chunking.namespace, manifest.chunking.name, manifest.chunking.semver
            )
            .as_str(),
        );

        let mut world = World::new();
        if let Some(status) = status {
            let digest = ManifestDigest::new(
                *manifest
                    .digest()
                    .expect("digest canonical PoR fixture")
                    .as_bytes(),
            );
            let mut record = PinManifestRecord::new(
                digest,
                ManifestRootCid::try_from_slice(&manifest.root_cid)
                    .expect("canonical PoR fixture root CID"),
                chunker_handle_for_manifest(&manifest),
                manifest.chunk_digest_sha3_256,
                manifest.por_root,
                manifest.content_length,
                registry_policy_for_manifest(&manifest),
                test_account(),
                5,
                None,
                None,
                Metadata::default(),
            );
            match status {
                PinStatus::Pending => {}
                PinStatus::Approved(epoch) => record.approve(epoch, None),
                PinStatus::Retired(epoch) => record.retire(epoch, None),
            }
            mutate_record(&mut record);
            world.pin_manifests_mut_for_testing().insert(digest, record);
        }

        let mut app = mk_app_state_for_tests_with_world(world);
        let app_inner = Arc::get_mut(&mut app).expect("unique PoR app state");
        #[cfg(feature = "telemetry")]
        {
            app_inner.telemetry = isolated_test_telemetry();
        }
        app_inner.sorafs_node = node;
        let core_state =
            Arc::get_mut(&mut app_inner.state).expect("unique PoR core state for finalization");
        let block_hash = HashOf::new(&default_block_header());
        let finalized_cursor = PinManifestFinalizedCursorV1 {
            height: 1,
            block_hash: *block_hash.as_ref(),
        };
        core_state.push_block_hash_for_testing(block_hash);
        (app, manifest, provider_id, finalized_cursor, storage_dir)
    }

    fn por_proof_stream_scope(
        manifest: &ManifestV1,
        provider_id: [u8; 32],
        finalized_cursor: PinManifestFinalizedCursorV1,
    ) -> sorafs_manifest::ProofStreamRequestV1 {
        sorafs_manifest::ProofStreamRequestV1 {
            manifest_digest: *manifest
                .digest()
                .expect("digest canonical PoR fixture")
                .as_bytes(),
            provider_id,
            proof_kind: ProofStreamKind::Por,
            challenge_id: None,
            sample_count: Some(3),
            deadline_ms: None,
            sample_seed: Some(7),
            expected_finalized_height: Some(finalized_cursor.height),
            expected_finalized_block_hash: Some(finalized_cursor.block_hash),
            nonce: [0xC2; 16],
            orchestrator_job_id: None,
            tier: Some(ProofStreamTier::Hot),
        }
    }

    #[tokio::test]
    async fn proof_stream_por_uses_only_the_approved_finalized_manifest_root() {
        let (state, manifest, provider_id, finalized_cursor, _storage_dir) =
            app_with_local_por_manifest(Some(PinStatus::Approved(7)), |_| {});
        let scope = por_proof_stream_scope(&manifest, provider_id, finalized_cursor);
        let request =
            ProofStreamHttpRequestV1::new(scope).expect("canonical authenticated PoR request");

        let (status, body) = proof_stream_body(
            handle_post_sorafs_proof_stream(State(state), JsonOnly(request)).await,
        )
        .await;

        assert_eq!(status, StatusCode::OK, "unexpected PoR response: {body}");
        let lines = body.lines().collect::<Vec<_>>();
        assert!(
            !lines.is_empty(),
            "PoR must return at least one verified row"
        );
        assert!(
            lines.len() <= 3,
            "PoR response must honor the request bound"
        );
        let context = ProofStreamVerificationContext::new(scope, Some(manifest.por_root))
            .expect("approved manifest root creates a closed PoR context");
        let mut sequence_verifier = ProofStreamSequenceVerifier::new(&context);
        for line in lines {
            let item = ProofStreamItem::from_ndjson(line.as_bytes(), &context)
                .expect("Torii emitted an approved-root PoR row");
            assert_eq!(item.proof_kind(), ProofStreamKind::Por);
            assert!(item.por_proof().is_some());
            sequence_verifier
                .verify_item(&item)
                .expect("Torii emitted the canonical request-bound sample order");
        }
        sequence_verifier
            .finish()
            .expect("Torii emitted the exact request-bound sample count");
    }

    #[cfg(feature = "telemetry")]
    #[tokio::test]
    async fn dropping_unpolled_por_response_records_no_success_and_releases_inflight() {
        let (state, manifest, provider_id, finalized_cursor, _storage_dir) =
            app_with_local_por_manifest(Some(PinStatus::Approved(7)), |_| {});
        let telemetry = state.telemetry.clone();
        let request = ProofStreamHttpRequestV1::new(por_proof_stream_scope(
            &manifest,
            provider_id,
            finalized_cursor,
        ))
        .expect("canonical authenticated PoR request");

        let response = handle_post_sorafs_proof_stream(State(state), JsonOnly(request)).await;
        assert_eq!(response.status(), StatusCode::OK);

        let metrics = telemetry.metrics().await;
        assert_eq!(
            metrics
                .torii_sorafs_proof_stream_events_total
                .with_label_values(&["por", "success", "ok"])
                .get(),
            0,
            "constructing an unpolled response must not record delivered proofs"
        );
        assert_eq!(
            metrics
                .torii_sorafs_proof_stream_inflight
                .with_label_values(&["por"])
                .get(),
            1,
            "the response body owns the in-flight guard until cancellation"
        );

        drop(response);

        assert_eq!(
            metrics
                .torii_sorafs_proof_stream_events_total
                .with_label_values(&["por", "success", "ok"])
                .get(),
            0,
            "cancelling before the first body poll must not record success"
        );
        assert_eq!(
            metrics
                .torii_sorafs_proof_stream_inflight
                .with_label_values(&["por"])
                .get(),
            0,
            "cancelling the body must release the in-flight guard"
        );
    }

    #[tokio::test]
    async fn proof_stream_por_rejects_missing_pending_retired_and_mismatched_pin_state() {
        for (label, status) in [
            ("missing", None),
            ("pending", Some(PinStatus::Pending)),
            ("retired", Some(PinStatus::Retired(8))),
        ] {
            let (state, manifest, provider_id, finalized_cursor, _storage_dir) =
                app_with_local_por_manifest(status, |_| {});
            let request = ProofStreamHttpRequestV1::new(por_proof_stream_scope(
                &manifest,
                provider_id,
                finalized_cursor,
            ))
            .expect("canonical negative PoR request");
            let (response_status, body) = proof_stream_body(
                handle_post_sorafs_proof_stream(State(state), JsonOnly(request)).await,
            )
            .await;
            assert_eq!(
                response_status,
                StatusCode::NOT_FOUND,
                "{label} pin state must fail closed: {body}"
            );
            assert!(
                !body.contains("\"proof\""),
                "{label} pin state must emit no proof rows"
            );
        }

        let (state, manifest, provider_id, finalized_cursor, _storage_dir) =
            app_with_local_por_manifest(Some(PinStatus::Approved(7)), |record| {
                record.por_root = [0xEE; 32];
            });
        let request = ProofStreamHttpRequestV1::new(por_proof_stream_scope(
            &manifest,
            provider_id,
            finalized_cursor,
        ))
        .expect("canonical mismatch PoR request");
        let (status, body) = proof_stream_body(
            handle_post_sorafs_proof_stream(State(state), JsonOnly(request)).await,
        )
        .await;
        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE);
        assert!(
            !body.contains("\"proof\""),
            "local/finalized PoR root mismatch must emit no proof rows"
        );
    }

    #[tokio::test]
    async fn proof_stream_pdp_and_potr_return_exact_finalized_chain_outcomes_without_storage() {
        let (state, challenge, receipt, finalized_cursor) = app_with_finalized_proof_outcomes();
        assert!(
            !state.sorafs_node.is_enabled(),
            "fixture deliberately has no process-local storage runtime"
        );

        let pdp_scope = sorafs_manifest::ProofStreamRequestV1 {
            manifest_digest: challenge.manifest_digest,
            provider_id: challenge.provider_id,
            proof_kind: ProofStreamKind::Pdp,
            challenge_id: Some(challenge.challenge_id),
            sample_count: None,
            deadline_ms: None,
            sample_seed: None,
            expected_finalized_height: Some(finalized_cursor.height),
            expected_finalized_block_hash: Some(finalized_cursor.block_hash),
            nonce: [0x12; 16],
            orchestrator_job_id: None,
            tier: None,
        };
        let pdp_request =
            ProofStreamHttpRequestV1::new(pdp_scope).expect("canonical PDP query envelope");
        let (status, body) = proof_stream_body(
            handle_post_sorafs_proof_stream(State(state.clone()), JsonOnly(pdp_request)).await,
        )
        .await;
        assert_eq!(status, StatusCode::OK, "unexpected PDP response: {body}");
        let pdp_lines = body.lines().collect::<Vec<_>>();
        assert_eq!(pdp_lines.len(), 1, "PDP lookup returns exactly one outcome");
        let pdp_context = ProofStreamVerificationContext::new(pdp_scope, None)
            .expect("canonical PDP verification context");
        let pdp = ProofStreamItem::from_ndjson(pdp_lines[0].as_bytes(), &pdp_context)
            .expect("parse finalized PDP row");
        assert_eq!(pdp.proof_kind(), sorafs_car::proof_stream::ProofKind::Pdp);
        assert_eq!(pdp.failure_reason(), Some("deadline_expired"));
        assert_eq!(pdp.finalized_block_height(), Some(finalized_cursor.height));
        assert_eq!(
            pdp.finalized_block_hash_hex(),
            Some(hex::encode(finalized_cursor.block_hash).as_str())
        );

        let request_id = receipt.request_id.expect("fixture request id");
        let potr_scope = sorafs_manifest::ProofStreamRequestV1 {
            manifest_digest: receipt.manifest_digest,
            provider_id: receipt.provider_id,
            proof_kind: ProofStreamKind::Potr,
            challenge_id: None,
            sample_count: None,
            deadline_ms: Some(receipt.deadline_ms),
            sample_seed: None,
            expected_finalized_height: Some(finalized_cursor.height),
            expected_finalized_block_hash: Some(finalized_cursor.block_hash),
            nonce: [0x13; 16],
            orchestrator_job_id: Some(request_id),
            tier: Some(receipt.tier),
        };
        let potr_request =
            ProofStreamHttpRequestV1::new(potr_scope).expect("canonical PoTR query envelope");
        let (status, body) = proof_stream_body(
            handle_post_sorafs_proof_stream(State(state), JsonOnly(potr_request)).await,
        )
        .await;
        assert_eq!(status, StatusCode::OK, "unexpected PoTR response: {body}");
        let potr_lines = body.lines().collect::<Vec<_>>();
        assert_eq!(
            potr_lines.len(),
            1,
            "exact PoTR scope must never fan out into receipt history"
        );
        let potr_context = ProofStreamVerificationContext::new(potr_scope, None)
            .expect("canonical PoTR verification context");
        let potr = ProofStreamItem::from_ndjson(potr_lines[0].as_bytes(), &potr_context)
            .expect("parse finalized PoTR row");
        assert_eq!(potr.proof_kind(), sorafs_car::proof_stream::ProofKind::Potr);
        assert_eq!(potr.potr_receipt(), Some(&receipt));
        assert_eq!(potr.finalized_block_height(), Some(finalized_cursor.height));
    }

