    fn encode_replication_order_bytes_with_providers(
        order_id: &ReplicationOrderId,
        manifest_digest: &ManifestDigest,
        manifest_cid: &[u8],
        providers: Vec<[u8; 32]>,
        issued_epoch: u64,
        deadline_epoch: u64,
    ) -> Vec<u8> {
        let target_replicas =
            u16::try_from(providers.len()).expect("fixture provider count fits u16");
        let ingest_deadline_secs = u32::try_from(deadline_epoch.saturating_sub(issued_epoch))
            .expect("fixture deadline delta fits u32");
        let order = ReplicationOrderV1 {
            version: REPLICATION_ORDER_VERSION_V1,
            order_id: *order_id.as_bytes(),
            manifest_cid: manifest_cid.to_vec(),
            manifest_digest: *manifest_digest.as_bytes(),
            chunking_profile: "sorafs.sf1@1.0.0".to_owned(),
            target_replicas,
            assignments: providers
                .into_iter()
                .map(|provider_id| ReplicationAssignmentV1 {
                    provider_id,
                    slice_gib: 1,
                    lane: None,
                })
                .collect(),
            issued_at: issued_epoch,
            deadline_at: deadline_epoch,
            sla: ReplicationOrderSlaV1 {
                ingest_deadline_secs,
                min_availability_percent_milli: 99_000,
                min_por_success_percent_milli: 98_000,
            },
            metadata: Vec::new(),
        };
        norito::to_bytes(&order).expect("encode replication order")
    }

    fn encode_replication_order_bytes(
        order_id: &ReplicationOrderId,
        manifest_digest: &ManifestDigest,
        manifest_root_cid: &ManifestRootCid,
        issued_epoch: u64,
        deadline_epoch: u64,
    ) -> Vec<u8> {
        let id_bytes = *order_id.as_bytes();
        let providers = vec![[id_bytes[0]; 32], [id_bytes[0].wrapping_add(1); 32]];
        encode_replication_order_bytes_with_providers(
            order_id,
            manifest_digest,
            manifest_root_cid.as_bytes(),
            providers,
            issued_epoch,
            deadline_epoch,
        )
    }

    fn fresh_alias_proof_bytes_for_test(alias: &str) -> Vec<u8> {
        let now = crate::sorafs::unix_now_secs();
        let generated_at_unix = now.saturating_sub(30);
        let expires_at_unix = now.saturating_add(3_600);
        let binding = AliasBindingV1 {
            alias: alias.to_owned(),
            manifest_cid: vec![0x42; 32],
            bound_at: generated_at_unix,
            expiry_epoch: expires_at_unix,
        };
        let merkle_path = Vec::new();
        let registry_root = alias_merkle_root(&binding, &merkle_path).expect("alias merkle root");
        let mut bundle = AliasProofBundleV1 {
            binding,
            registry_root,
            registry_height: 1,
            generated_at_unix,
            expires_at_unix,
            merkle_path,
            council_signatures: Vec::new(),
        };
        let message = alias_proof_signature_digest(&bundle);
        let keypair = checked_test_keypair(0x28);
        let signature = checked_test_signature(keypair.private_key(), message.as_ref());
        let mut signer = [0_u8; 32];
        signer.copy_from_slice(
            keypair
                .public_key()
                .try_to_bytes()
                .expect("fixture public key must be valid")
                .1,
        );
        bundle.council_signatures.push(CouncilSignature {
            signer,
            signature: signature.payload().to_vec(),
        });
        norito::to_bytes(&bundle).expect("encode fresh alias proof bundle")
    }

