    fn manifest_for_payload(seed: u8, payload: &[u8]) -> ManifestV1 {
        let plan = CarBuildPlan::single_file(payload).expect("canonical fixture chunk plan");
        let manifest = ManifestBuilder::new()
            .root_cid(sorafs_manifest::canonical_manifest_root_cid(
                [seed.max(1); 32],
            ))
            .dag_codec(DagCodecId(0x71))
            .chunking_from_profile(
                sorafs_chunker::ChunkProfile::DEFAULT,
                sorafs_manifest::BLAKE3_256_MULTIHASH_CODE,
            )
            .chunk_digest_sha3_256(compute_chunk_plan_digest_sha3(&plan.chunks))
            .por_root(
                sorafs_car::compute_por_root(payload, &plan)
                    .expect("derive canonical fixture PoR root"),
            )
            .content_length(payload.len() as u64)
            .car_digest(blake3::hash(payload).into())
            .car_size(payload.len() as u64)
            .pin_policy(PinPolicy::default())
            .governance(test_governance_proofs())
            .push_alias(AliasClaim {
                name: "test".into(),
                namespace: "alias".into(),
                proof: vec![0xAA; 16],
            })
            .build()
            .expect("manifest");
        manifest
    }

    fn seed_capacity_declaration(
        node: &sorafs_node::NodeHandle,
        provider_id: [u8; 32],
        chunker_handle: &str,
    ) {
        let declaration = CapacityDeclarationV1 {
            version: CAPACITY_DECLARATION_VERSION_V1,
            provider_id,
            stake: StakePointer {
                pool_id: [0x5A; 32],
                stake_amount: "1".parse().expect("canonical XOR stake"),
            },
            committed_capacity_gib: 1,
            chunker_commitments: vec![ChunkerCommitmentV1 {
                profile_id: chunker_handle.to_string(),
                profile_aliases: None,
                committed_gib: 1,
                capability_refs: vec![
                    CapabilityType::ToriiGateway,
                    CapabilityType::ChunkRangeFetch,
                ],
            }],
            lane_commitments: Vec::new(),
            pricing: None,
            valid_from: 0,
            valid_until: 10,
            metadata: Vec::new(),
        };
        let declaration_bytes =
            to_bytes(&declaration).expect("encode capacity declaration fixture");
        let record = CapacityDeclarationRecord::new(
            ProviderId::new(provider_id),
            declaration_bytes,
            declaration.committed_capacity_gib,
            0,
            0,
            10,
            Metadata::default(),
        );
        node.reconcile_finalized_capacity(
            sorafs_node::capacity::CapacityFinalizedCursorV1 {
                height: 1,
                block_hash: [0xC1; 32],
            },
            sorafs_node::capacity::CapacityReconcileModeV1::FullRebuild,
            record.provider_id,
            Some(&record),
            &[],
        )
        .expect("reconcile capacity declaration");
    }

